return ['domain'=>'iminify-image-optimizer','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'de_DE','project-id-version'=>'Iminify Image Optimizer 1.0.0','pot-creation-date'=>'2026-11-10T02:17:25+00:00','po-revision-date'=>'2026-11-10 02:17+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Iminify Image Optimizer'=>'Iminify Image Optimizer','https://www.iminify.com'=>'https://www.iminify.com','Compress, convert and resize the images in your media library with Iminify, and serve them as WebP and AVIF.'=>'Komprimiere, konvertiere und skaliere die Bilder in deiner Mediathek mit Iminify und liefere sie als WebP und AVIF aus.','Iminify'=>'Iminify','Page Audit'=>'Seitenprüfung','Find the images that slow your pages down, each beside the image in your library it is.'=>'Finde die Bilder, die deine Seiten ausbremsen, jeweils neben dem zugehörigen Bild aus deiner Mediathek.','The page\'s script is missing from the plugin\'s folder. Reinstall the plugin to bring it back.'=>'Das Skript dieser Seite fehlt im Ordner des Plugins. Installiere das Plugin neu, um es wiederherzustellen.','This page needs JavaScript.'=>'Diese Seite benötigt JavaScript.','Original upload'=>'Ursprünglicher Upload','Home page'=>'Homepage','Sorry, you are not allowed to do that.'=>'Du bist leider nicht berechtigt, diese Aktion durchzuführen.','Bulk Optimization'=>'Massenoptimierung','Every image already in your media library, in one run.'=>'Alle Bilder, die bereits in deiner Mediathek sind, in einem Durchlauf.','The bulk page\'s script is missing from the plugin\'s folder. Reinstall the plugin to bring it back.'=>'Das Skript der Massenoptimierung fehlt im Ordner des Plugins. Installiere das Plugin neu, um es wiederherzustellen.','The bulk page needs JavaScript.'=>'Die Massenoptimierung benötigt JavaScript.','That folder isn\'t in the list.'=>'Dieser Ordner ist nicht in der Liste.','That image isn\'t in the list.'=>'Dieses Bild ist nicht in der Liste.','Other Folders'=>'Weitere Ordner','The images in your theme and other folders outside the media library.'=>'Die Bilder in deinem Theme und in anderen Ordnern außerhalb der Mediathek.','This image has no original on the site to compare it with.'=>'Für dieses Bild gibt es auf der Website kein Original zum Vergleichen.','Original'=>'Original','Compare with the original'=>'Mit dem Original vergleichen','Close'=>'Schließen','How much of the original shows'=>'Wie viel vom Original zu sehen ist','The optimized file to compare'=>'Optimierte Datei zum Vergleichen','This image couldn\'t be loaded from the site.'=>'Dieses Bild konnte nicht von der Website geladen werden.','Drag the line, or use the arrow keys, to see more of the original on one side and of the optimized file on the other.'=>'Ziehe die Linie oder nutze die Pfeiltasten, um auf der einen Seite mehr vom Original und auf der anderen mehr von der optimierten Datei zu sehen.','Optimized at %s. Drag the line, or use the arrow keys, to see more of the original on one side and of the optimized file on the other.'=>'Optimiert mit %s. Ziehe die Linie oder nutze die Pfeiltasten, um auf der einen Seite mehr vom Original und auf der anderen mehr von der optimierten Datei zu sehen.','%1$s, %2$s'=>'%1$s, %2$s','%1$s, %2$s smaller'=>'%1$s, %2$s kleiner','Optimized'=>'Optimiert','Optimize again from the original'=>'Erneut aus dem Original optimieren','Restore original'=>'Original wiederherstellen','Optimize again'=>'Erneut optimieren','Optimize'=>'Optimieren','Filter by Iminify status'=>'Nach Iminify-Status filtern','All Iminify statuses'=>'Alle Iminify-Status','Not optimized'=>'Nicht optimiert','Errors'=>'Fehler','Missing formats'=>'Fehlende Formate','Optimized by another plugin'=>'Von einem anderen Plugin optimiert','Offloaded by %s'=>'Ausgelagert von %s','Saved %1$s (%2$s) across %3$s file.'=>'%1$s (%2$s) eingespart bei %3$s Datei.' . "\0" . '%1$s (%2$s) eingespart bei %3$s Dateien.','The originals were already smaller, so they were kept.'=>'Die Originale waren bereits kleiner und wurden daher behalten.','Copies: %s'=>'Kopien: %s','Missing formats: %s'=>'Fehlende Formate: %s','Missing sizes: %s'=>'Fehlende Größen: %s','%s WebP or AVIF copy another tool made was kept as it is.'=>'%s WebP- oder AVIF-Kopie, die ein anderes Tool erstellt hat, wurde unverändert behalten.' . "\0" . '%s WebP- oder AVIF-Kopien, die ein anderes Tool erstellt hat, wurden unverändert behalten.','%s file couldn\'t be written.'=>'%s Datei konnte nicht geschrieben werden.' . "\0" . '%s Dateien konnten nicht geschrieben werden.','%1$s saved %2$s (%3$s), as it recorded it.'=>'%1$s hat laut eigener Aufzeichnung %2$s (%3$s) eingespart.','Its original is kept. Iminify leaves the image as it is, and it costs nothing.'=>'Sein Original wurde behalten. Iminify lässt das Bild unverändert, und es kostet nichts.','No original of it was kept, so Iminify leaves it as it is rather than compress it a second time.'=>'Davon wurde kein Original behalten, daher lässt Iminify es unverändert, statt es ein zweites Mal zu komprimieren.','Queued'=>'In der Warteschlange','Being optimized'=>'Wird optimiert','Waiting for the next batch'=>'Wartet auf das nächste Kontingent','Waiting for the connection'=>'Wartet auf die Verbindung','Not sent'=>'Nicht gesendet','Error'=>'Fehler','The next batch is open, so it goes out shortly.'=>'Das nächste Kontingent ist freigegeben, daher wird es in Kürze gesendet.','It goes out by itself on %s.'=>'Es wird am %s automatisch gesendet.','Alt text: being written.'=>'Alternativtext: wird geschrieben.','Alt text: written by Iminify.'=>'Alternativtext: von Iminify geschrieben.','Alt text: yours was kept.'=>'Alternativtext: deiner wurde behalten.','Alt text: Iminify couldn\'t write one for this image.'=>'Alternativtext: Iminify konnte für dieses Bild keinen schreiben.','Alt text: not written, as the day\'s AI alt texts were used up.'=>'Alternativtext: nicht geschrieben, da die KI-Alternativtexte für heute aufgebraucht waren.','This image carries Content Credentials, a signed record of where it came from, and its files keep them.'=>'Dieses Bild enthält Content Credentials, einen signierten Nachweis seiner Herkunft, und seine Dateien behalten sie.','This image carried Content Credentials, a signed record of where it came from. The files and copies Iminify wrote leave them out, since a new file breaks their signature, and the original kept as a backup still has them.'=>'Dieses Bild enthielt Content Credentials, einen signierten Nachweis seiner Herkunft. Die Dateien und Kopien, die Iminify geschrieben hat, enthalten sie nicht, da eine neue Datei ihre Signatur ungültig macht. Das als Backup behaltene Original enthält sie noch.','This image carried Content Credentials, a signed record of where it came from. The files and copies Iminify wrote leave them out, since a new file breaks their signature.'=>'Dieses Bild enthielt Content Credentials, einen signierten Nachweis seiner Herkunft. Die Dateien und Kopien, die Iminify geschrieben hat, enthalten sie nicht, da eine neue Datei ihre Signatur ungültig macht.','They say generative AI made it, wholly or in part.'=>'Laut diesen Angaben wurde es ganz oder teilweise mit generativer KI erstellt.','WebP'=>'WebP','AVIF'=>'AVIF','Its pages are served the %1$s copies %2$s made, until Iminify makes its own.'=>'Auf den Seiten mit diesem Bild werden die Kopien in %1$s ausgeliefert, die %2$s erstellt hat, bis Iminify eigene erstellt.','Full Size'=>'Originalgröße','Level: %s'=>'Stufe: %s','Size'=>'Größe','Before'=>'Vorher','After'=>'Nachher','Copies'=>'Kopien','Write alt text with AI'=>'Alternativtext mit KI schreiben','Send a small copy of this image to write its alt text? It counts as one of your AI alt texts for the day.'=>'Eine verkleinerte Version dieses Bildes senden, um seinen Alternativtext zu schreiben? Das zählt als einer deiner KI-Alternativtexte für heute.','Write alt text'=>'Alternativtext schreiben','Optimize again from the original at'=>'Erneut aus dem Original optimieren mit','Connect the site to Iminify to optimize this image.'=>'Verbinde die Website mit Iminify, um dieses Bild zu optimieren.','No original of this image was kept, so it can\'t be optimized again or restored.'=>'Von diesem Bild wurde kein Original behalten, daher kann es weder erneut optimiert noch wiederhergestellt werden.','Optimize again at'=>'Erneut optimieren mit','Optimize at'=>'Optimieren mit','Make what it lacks'=>'Fehlendes erstellen','This image has changed since Iminify optimized it, so there\'s nothing to restore.'=>'Dieses Bild wurde geändert, seit Iminify es optimiert hat, daher gibt es nichts wiederherzustellen.','Delete the copies'=>'Kopien löschen','Delete this image\'s WebP and AVIF copies? Its pages go back to serving the JPEG or PNG.'=>'Die WebP- und AVIF-Kopien dieses Bildes löschen? Seine Seiten liefern dann wieder das JPEG oder PNG aus.','Make the missing formats'=>'Fehlende Formate erstellen','Make the missing sizes'=>'Fehlende Größen erstellen','Send this image again to make what it lacks? This counts as one more image, and its other files stay as they are unless Iminify makes them smaller.'=>'Dieses Bild erneut senden, um das Fehlende zu erstellen? Das zählt als ein weiteres Bild, und seine übrigen Dateien bleiben unverändert, sofern Iminify sie nicht verkleinert.','Optimize this image again? Iminify makes its files again from its original, keeping their format and names, and this counts as one more image.'=>'Dieses Bild erneut optimieren? Iminify erstellt seine Dateien aus dem Original neu, mit gleichem Format und gleichen Namen, und das zählt als ein weiteres Bild.','Optimize this image again? Its original goes back first, and this counts as one more image.'=>'Dieses Bild erneut optimieren? Zuerst wird sein Original wieder eingesetzt, und das zählt als ein weiteres Bild.','Restore the original of this image? WordPress makes its sizes again, and its WebP and AVIF copies are deleted.'=>'Das Original dieses Bildes wiederherstellen? WordPress erstellt seine Größen neu, und seine WebP- und AVIF-Kopien werden gelöscht.','Optimize this image again from the original %s kept? Iminify makes its files again from it, keeping their format and names so your posts still link to them, and keeps its own backup of the original. This counts as one more image.'=>'Dieses Bild erneut aus dem Original optimieren, das %s behalten hat? Iminify erstellt seine Dateien daraus neu, mit gleichem Format und gleichen Namen, damit deine Beiträge weiterhin darauf verlinken, und behält ein eigenes Backup des Originals. Das zählt als ein weiteres Bild.','Optimize this image again from the original %s kept? The original goes back first and WordPress makes its sizes again, then Iminify optimizes it and keeps its own backup of the original. This counts as one more image.'=>'Dieses Bild erneut aus dem Original optimieren, das %s behalten hat? Zuerst wird das Original wieder eingesetzt und WordPress erstellt seine Größen neu, dann optimiert Iminify es und behält ein eigenes Backup des Originals. Das zählt als ein weiteres Bild.','Restore the original of this image from what %s kept? WordPress makes its sizes again, and that plugin\'s backups and copies stay where they are.'=>'Das Original dieses Bildes aus dem wiederherstellen, was %s behalten hat? WordPress erstellt seine Größen neu, und die Backups und Kopien dieses Plugins bleiben, wo sie sind.','Iminify disconnected this site, so new uploads aren\'t optimized.'=>'Iminify hat die Verbindung dieser Website getrennt, daher werden neue Uploads nicht optimiert.','Connect it again'=>'Erneut verbinden','Iminify Image Optimizer is ready. Connect it to your Iminify account to start optimizing your images.'=>'Iminify Image Optimizer ist bereit. Verbinde es mit deinem Iminify-Konto, um deine Bilder zu optimieren.','Connect'=>'Verbinden','Open the Iminify settings'=>'Iminify-Einstellungen öffnen','Connected'=>'Verbunden','Not connected'=>'Nicht verbunden','Iminify Image Optimizer sends the images uploaded to this site to Iminify, an image optimization service, once the site is connected to it. You can copy the text below into the part of your policy about the media you publish.'=>'Iminify Image Optimizer sendet die auf diese Website hochgeladenen Bilder an Iminify, einen Dienst zur Bildoptimierung, sobald die Website damit verbunden ist. Du kannst den folgenden Text in den Abschnitt deiner Datenschutzerklärung übernehmen, der die von dir veröffentlichten Medien betrifft.','Suggested text:'=>'Textvorschlag:','This site uses Iminify (www.iminify.com) to make its images smaller and to make WebP and AVIF copies of them. When an image is uploaded here, or we optimize the images already here, in the media library or in our theme and other folders, our server sends it to Iminify with this site\'s address, and Iminify sends the smaller files back. Iminify deletes the image once we have saved them.'=>'Diese Website verwendet Iminify (www.iminify.com), um ihre Bilder zu verkleinern und WebP- und AVIF-Kopien davon zu erstellen. Wenn hier ein Bild hochgeladen wird oder wir die bereits vorhandenen Bilder optimieren, in der Mediathek oder in unserem Theme und anderen Ordnern, sendet unser Server es zusammen mit der Adresse dieser Website an Iminify, und Iminify sendet die kleineren Dateien zurück. Iminify löscht das Bild, sobald wir sie gespeichert haben.','A photo can carry details the camera wrote into it, such as when and where it was taken. Those details reach Iminify with the image, and Iminify leaves them out of the files it sends back unless we chose to keep them.'=>'Ein Foto kann Angaben enthalten, die die Kamera hineingeschrieben hat, etwa wann und wo es aufgenommen wurde. Diese Angaben erreichen Iminify zusammen mit dem Bild, und Iminify lässt sie in den zurückgesendeten Dateien weg, sofern wir nicht festgelegt haben, sie zu behalten.','If we turned on AI alt text in the plugin\'s settings, Iminify also makes a small copy of each image that has no alt text and sends it to Anthropic, whose model writes a description of it. Asking for alt text for images already in the media library sends Iminify a small copy of each of them for the same use.'=>'Wenn wir in den Einstellungen des Plugins KI-Alternativtexte aktiviert haben, erstellt Iminify außerdem eine verkleinerte Version jedes Bildes ohne Alternativtext und sendet sie an Anthropic, dessen Modell eine Beschreibung davon schreibt. Werden Alternativtexte für Bilder angefordert, die bereits in der Mediathek sind, erhält Iminify zum selben Zweck eine verkleinerte Version jedes dieser Bilder.','If we audit one of this site\'s pages for its images, our server sends Iminify that page\'s address. Iminify opens the page as any visitor could, measures the images it shows and keeps what it found with this site\'s connection to it.'=>'Wenn wir eine der Seiten dieser Website auf ihre Bilder prüfen, sendet unser Server Iminify die Adresse dieser Seite. Iminify öffnet die Seite so, wie es jeder Besucher könnte, misst die angezeigten Bilder und speichert das Ergebnis zusammen mit der Verbindung dieser Website.','Where this site is part of a multisite network connected to Iminify as one, our server also sends Iminify this site\'s address and name the first time the site needs it.'=>'Wenn diese Website Teil eines Multisite-Netzwerks ist, das als Ganzes mit Iminify verbunden ist, sendet unser Server Iminify außerdem die Adresse und den Namen dieser Website, sobald die Website die Verbindung zum ersten Mal braucht.','If we choose to use the settings another image optimizer kept on this site, our server sends Iminify those settings, that optimizer\'s name and the names of the image sizes this site makes. Iminify answers with the settings they match and keeps none of it.'=>'Wenn wir die Einstellungen übernehmen, die ein anderer Bildoptimierer auf dieser Website gespeichert hat, sendet unser Server Iminify diese Einstellungen, den Namen dieses Optimierers und die Namen der Bildgrößen, die diese Website erstellt. Iminify antwortet mit den passenden Einstellungen und speichert nichts davon.','Nothing about the people who visit this site is sent to Iminify: the images on our pages, and their WebP and AVIF copies, are served from this site.'=>'Über die Besucher dieser Website wird nichts an Iminify gesendet: Die Bilder auf unseren Seiten und ihre WebP- und AVIF-Kopien werden von dieser Website ausgeliefert.','Iminify\'s privacy policy: %s'=>'Datenschutzerklärung von Iminify: %s','Only a site of a network the plugin is active for can join it.'=>'Nur eine Website eines Netzwerks, in dem das Plugin aktiv ist, kann ihm beitreten.','This site isn\'t connected to Iminify.'=>'Diese Website ist nicht mit Iminify verbunden.','The plugin found no settings of that optimizer on this site.'=>'Das Plugin hat auf dieser Website keine Einstellungen dieses Optimierers gefunden.','Those settings changed since they were shown. Look at them again before using them.'=>'Diese Einstellungen haben sich geändert, seit sie angezeigt wurden. Sieh sie dir erneut an, bevor du sie übernimmst.','Optimize new uploads'=>'Neue Uploads optimieren','Compression level'=>'Komprimierungsstufe','Make WebP copies'=>'WebP-Kopien erstellen','Make AVIF copies'=>'AVIF-Kopien erstellen','Maximum width, in pixels'=>'Maximale Breite in Pixeln','Size limit, in KB'=>'Maximale Dateigröße in KB','Keep metadata'=>'Metadaten behalten','Sizes to optimize'=>'Zu optimierende Größen','Keep a backup of each original'=>'Ein Backup jedes Originals behalten','No limit'=>'Kein Limit','Every size'=>'Alle Größen','Only the full image'=>'Nur die Originalgröße','On'=>'An','Off'=>'Aus','Settings'=>'Einstellungen','Connect this site and choose how its images are optimized.'=>'Verbinde diese Website und lege fest, wie ihre Bilder optimiert werden.','Connect this network once, and each of its sites joins by itself.'=>'Verbinde dieses Netzwerk einmal, und jede seiner Websites tritt automatisch bei.','The settings page\'s script is missing from the plugin\'s folder. Reinstall the plugin to bring it back.'=>'Das Skript der Einstellungsseite fehlt im Ordner des Plugins. Installiere das Plugin neu, um es wiederherzustellen.','The settings page needs JavaScript.'=>'Die Einstellungsseite benötigt JavaScript.','Images today'=>'Bilder heute','Files today'=>'Dateien heute','AI alt texts today'=>'KI-Alternativtexte heute','Guest'=>'Gast','Free'=>'Kostenlos','Pro trial'=>'Pro-Testphase','Pro'=>'Pro','Max'=>'Max','This site'=>'Diese Website','Your whole account'=>'Dein gesamtes Konto','Thumbnail'=>'Vorschaubild','Medium'=>'Mittel','Large'=>'Groß','%1$s (%2$d wide)'=>'%1$s (%2$d breit)','%1$s (%2$d high)'=>'%1$s (%2$d hoch)','%1$s (%2$d × %3$d)'=>'%1$s (%2$d × %3$d)','Iminify couldn\'t be reached: %s'=>'Iminify war nicht erreichbar: %s','Iminify answered with an error (HTTP %d).'=>'Iminify hat mit einem Fehler geantwortet (HTTP %d).','Iminify sent an answer this version of the plugin can\'t read.'=>'Iminify hat eine Antwort gesendet, die diese Version des Plugins nicht lesen kann.','This server doesn\'t have the memory to send an image this large.'=>'Diesem Server fehlt der Arbeitsspeicher, um ein so großes Bild zu senden.','The image couldn\'t be read from the uploads folder.'=>'Das Bild konnte nicht aus dem Uploads-Ordner gelesen werden.','Show a smaller size of the image here.'=>'Zeige hier eine kleinere Größe des Bildes an.','Show a size about %s pixels wide here, twice the width it takes on the page.'=>'Zeige hier eine Größe mit etwa %s Pixeln Breite an, doppelt so breit wie der Platz, den es auf der Seite einnimmt.','Give the image its width and height in the page.'=>'Gib auf der Seite die Breite und Höhe des Bildes an.','Write alt text for the image.'=>'Schreibe einen Alternativtext für das Bild.','Load the image straight away, not lazily.'=>'Lade das Bild sofort, nicht per Lazy Loading.','Load the image lazily, once a visitor scrolls near it.'=>'Lade das Bild per Lazy Loading, sobald ein Besucher in seine Nähe scrollt.','Have the browser fetch the image first.'=>'Lass den Browser das Bild zuerst abrufen.','Oversized'=>'Zu groß','The file is more than twice as wide and twice as tall as the space it is shown in. A smaller size of the same image would look as sharp.'=>'Die Datei ist mehr als doppelt so breit und doppelt so hoch wie der Platz, in dem sie angezeigt wird. Eine kleinere Größe desselben Bildes würde genauso scharf aussehen.','No width and height'=>'Ohne Breite und Höhe','The image has no width and height attributes, so the browser can\'t hold its space and the page moves when it arrives.'=>'Das Bild hat keine width- und height-Attribute, daher kann der Browser seinen Platz nicht freihalten, und die Seite verschiebt sich, wenn es ankommt.','Lazy in the first screen'=>'Lazy im ersten Bildschirm','The image is in the first screen but is lazy loaded, which delays it.'=>'Das Bild liegt im ersten Bildschirm, wird aber per Lazy Loading geladen, was es verzögert.','Loads too early'=>'Lädt zu früh','The image is below the first screen and loads straight away, competing with what visitors see first.'=>'Das Bild liegt unterhalb des ersten Bildschirms und lädt sofort, in Konkurrenz zu dem, was Besucher zuerst sehen.','No alt text'=>'Kein Alternativtext','The image has no alt text for screen readers and search engines.'=>'Das Bild hat keinen Alternativtext für Screenreader und Suchmaschinen.','Not prioritized'=>'Nicht priorisiert','This is the largest thing in the first screen, so the page feels loaded when it arrives. Fetching it first would show the page sooner.'=>'Das ist das größte Element im ersten Bildschirm, daher wirkt die Seite geladen, sobald es ankommt. Würde es zuerst abgerufen, wäre die Seite schneller zu sehen.','Your site turned the scanner away, so the page couldn\'t be read. A firewall or a bot check does this, often Cloudflare\'s. Let the scan through for a moment: in Cloudflare, turn Bot Fight Mode off or set the Security Level to "Essentially off"; in a security plugin, pause its firewall or its bot blocking. Scan again, then turn them back on.'=>'Deine Website hat den Scanner abgewiesen, daher konnte die Seite nicht gelesen werden. Das tut eine Firewall oder eine Bot-Prüfung, oft die von Cloudflare. Lass den Scan für einen Moment durch: Schalte in Cloudflare „Bot Fight Mode“ aus oder setze das „Security Level“ auf „Essentially off“; pausiere in einem Sicherheits-Plugin dessen Firewall oder Bot-Sperre. Scanne erneut und schalte sie danach wieder ein.','Your site turned the scanner away (it answered %d), so the page couldn\'t be read. A firewall or a bot check does this, often Cloudflare\'s. Let the scan through for a moment: in Cloudflare, turn Bot Fight Mode off or set the Security Level to "Essentially off"; in a security plugin, pause its firewall or its bot blocking. Scan again, then turn them back on.'=>'Deine Website hat den Scanner abgewiesen (sie antwortete mit %d), daher konnte die Seite nicht gelesen werden. Das tut eine Firewall oder eine Bot-Prüfung, oft die von Cloudflare. Lass den Scan für einen Moment durch: Schalte in Cloudflare „Bot Fight Mode“ aus oder setze das „Security Level“ auf „Essentially off“; pausiere in einem Sicherheits-Plugin dessen Firewall oder Bot-Sperre. Scanne erneut und schalte sie danach wieder ein.','There is no page at this address. Check the address and scan again.'=>'Unter dieser Adresse gibt es keine Seite. Prüfe die Adresse und scanne erneut.','The page answered with an error on the site\'s side, so it couldn\'t be read. Scan again in a few minutes.'=>'Die Seite hat mit einem Fehler auf Seiten der Website geantwortet, daher konnte sie nicht gelesen werden. Scanne in ein paar Minuten erneut.','The page sent the scanner to another site, which an audit doesn\'t follow. Scan the address the page ends up at, if it is on this site.'=>'Die Seite hat den Scanner auf eine andere Website weitergeleitet, und dem folgt eine Prüfung nicht. Scanne die Adresse, bei der die Seite landet, falls sie auf dieser Website liegt.','The page couldn\'t be read: the site didn\'t answer the scanner. Check the address and scan again.'=>'Die Seite konnte nicht gelesen werden: Die Website hat dem Scanner nicht geantwortet. Prüfe die Adresse und scanne erneut.','The page answered %d instead of the page, so it couldn\'t be read. Check the address and scan again.'=>'Die Adresse hat mit %d statt mit der Seite geantwortet, daher konnte die Seite nicht gelesen werden. Prüfe die Adresse und scanne erneut.','Pass --others alone, or with the attachments to optimize again.'=>'Gib --others allein an oder zusammen mit den Anhängen, die erneut optimiert werden sollen.','The folders\' files go all at once: pass --folders alone, or with --failed.'=>'Die Dateien der Ordner werden alle auf einmal verarbeitet: Gib --folders allein oder mit --failed an.','Name the attachments, or pass --all or --failed.'=>'Nenne die Anhänge oder gib --all oder --failed an.','The folders\' files go all at once: pass --folders alone.'=>'Die Dateien der Ordner werden alle auf einmal verarbeitet: Gib --folders allein an.','Put every optimized file in your folders back as it was?'=>'Jede optimierte Datei in deinen Ordnern wieder in ihren ursprünglichen Zustand zurücksetzen?','Name the attachments, or pass --all.'=>'Nenne die Anhänge oder gib --all an.','Put every optimized image back as it was uploaded?'=>'Jedes optimierte Bild wieder so zurücksetzen, wie es hochgeladen wurde?','Say what to make: formats or sizes.'=>'Gib an, was erstellt werden soll: formats oder sizes.','On a network, other folders are chosen on the main site: add --url with its address.'=>'In einem Netzwerk werden weitere Ordner auf der Hauptwebsite ausgewählt: Füge --url mit deren Adresse hinzu.','Name the folder, relative to wp-content.'=>'Nenne den Ordner, relativ zu wp-content.','Found %1$s images: %2$s new, %3$s changed.'=>'%1$s Bilder gefunden: %2$s neu, %3$s geändert.','No bulk run is going.'=>'Es läuft keine Massenoptimierung.','Stopped.'=>'Angehalten.','The run goes on in the background. See how far it got with: wp iminify status'=>'Der Durchlauf geht im Hintergrund weiter. Den Fortschritt siehst du mit: wp iminify status','Bulk run'=>'Massenoptimierung','The account\'s AI alt texts for the day are used up. The run goes on in the background when they come back on %s.'=>'Die KI-Alternativtexte des Kontos für heute sind aufgebraucht. Der Durchlauf geht im Hintergrund weiter, wenn sie am %s wieder verfügbar sind.','The run waits for this site\'s connection to Iminify, and goes on in the background once it works.'=>'Der Durchlauf wartet auf die Verbindung dieser Website zu Iminify und geht im Hintergrund weiter, sobald sie funktioniert.','The run goes on in the background once it stops.'=>'Der Durchlauf geht im Hintergrund weiter, sobald das andere Plugin damit aufhört.','The account\'s images for the day are used up. The run goes on in the background when the next batch opens on %s.'=>'Die Bilder des Kontos für heute sind aufgebraucht. Der Durchlauf geht im Hintergrund weiter, wenn am %s das nächste Kontingent freigegeben wird.','The run was stopped.'=>'Der Durchlauf wurde angehalten.','The run paused: the server is low on disk space. Free some up, then run: wp iminify run'=>'Der Durchlauf wurde pausiert: Auf dem Server wird der Speicherplatz knapp. Gib etwas frei und führe dann aus: wp iminify run','The run was paused. Carry on with: wp iminify run'=>'Der Durchlauf wurde pausiert. Fortsetzen mit: wp iminify run','%s image couldn\'t be restored. Its panel in the media library says why.'=>'%s Bild konnte nicht wiederhergestellt werden. Sein Panel in der Mediathek nennt den Grund.' . "\0" . '%s Bilder konnten nicht wiederhergestellt werden. Ihre Panels in der Mediathek nennen den Grund.','%s image was left as it is: another plugin converted it to WebP or AVIF, and only that plugin can put its original back.'=>'%s Bild wurde unverändert belassen: Ein anderes Plugin hat es in WebP oder AVIF konvertiert, und nur dieses Plugin kann sein Original zurückholen.' . "\0" . '%s Bilder wurden unverändert belassen: Andere Plugins haben sie in WebP oder AVIF konvertiert, und nur diese Plugins können ihre Originale zurückholen.','%s image was left as the other plugin made it: its original is gone, too large to send, or only that plugin can put it back. Its panel in the media library says which.'=>'%s Bild wurde so belassen, wie das andere Plugin es erstellt hat: Sein Original fehlt, ist zu groß zum Senden, oder nur dieses Plugin kann es zurückholen. Sein Panel in der Mediathek nennt, was davon zutrifft.' . "\0" . '%s Bilder wurden so belassen, wie die anderen Plugins sie erstellt haben: Ihre Originale fehlen, sind zu groß zum Senden, oder nur diese Plugins können sie zurückholen. Ihre Panels in der Mediathek nennen, was davon zutrifft.','%s image was left as it is: it shares its files with another attachment, or has alt text by now.'=>'%s Bild wurde unverändert belassen: Es teilt seine Dateien mit einem anderen Anhang oder hat inzwischen einen Alternativtext.' . "\0" . '%s Bilder wurden unverändert belassen: Sie teilen ihre Dateien mit einem anderen Anhang oder haben inzwischen einen Alternativtext.','%s image has no original to go from, or changed since it was optimized, so nothing was made for it.'=>'%s Bild hat kein Original als Ausgangspunkt oder wurde seit der Optimierung geändert, daher wurde nichts dafür erstellt.' . "\0" . '%s Bilder haben kein Original als Ausgangspunkt oder wurden seit der Optimierung geändert, daher wurde nichts für sie erstellt.','%s file restored.'=>'%s Datei wiederhergestellt.' . "\0" . '%s Dateien wiederhergestellt.','%s file sent to Iminify.'=>'%s Datei an Iminify gesendet.' . "\0" . '%s Dateien an Iminify gesendet.','Your folders have %1$s of %2$s files optimized, %3$s failed.'=>'In deinen Ordnern sind %1$s von %2$s Dateien optimiert, %3$s fehlgeschlagen.','%s image restored.'=>'%s Bild wiederhergestellt.' . "\0" . '%s Bilder wiederhergestellt.','%s image sent to Iminify.'=>'%s Bild an Iminify gesendet.' . "\0" . '%s Bilder an Iminify gesendet.','The library has %1$s of %2$s images optimized, %3$s failed.'=>'In der Mediathek sind %1$s von %2$s Bildern optimiert, %3$s fehlgeschlagen.','%s isn\'t an attachment.'=>'%s ist kein Anhang.','This account can\'t run bulk commands.'=>'Dieses Benutzerkonto kann keine Massenbefehle ausführen.','Paste the site key first.'=>'Füge zuerst den Website-Schlüssel ein.','This site\'s key is set in wp-config.php. Change or remove it there.'=>'Der Schlüssel dieser Website ist in wp-config.php festgelegt. Ändere oder entferne ihn dort.','WordPress couldn\'t store the site key. Press Connect to try again.'=>'WordPress konnte den Website-Schlüssel nicht speichern. Klicke auf „Verbinden“, um es erneut zu versuchen.','Waiting to go on: the plugin was turned off while this image was on its way.'=>'Wartet auf Fortsetzung: Das Plugin wurde deaktiviert, während dieses Bild unterwegs war.','Smart'=>'Smart','Smart: a balance between quality and size'=>'Smart: ein Mittelweg zwischen Qualität und Dateigröße','A balance between quality and size.'=>'Ein Mittelweg zwischen Qualität und Dateigröße.','Ultra'=>'Ultra','Ultra: the smallest files, with some loss of quality'=>'Ultra: die kleinsten Dateien, mit etwas Qualitätsverlust','The smallest files, with some loss of quality.'=>'Die kleinsten Dateien, mit etwas Qualitätsverlust.','Lossless'=>'Verlustfrei','Lossless: no visible change in quality'=>'Verlustfrei: keine sichtbare Änderung der Qualität','No visible change in quality.'=>'Keine sichtbare Änderung der Qualität.','None'=>'Keine','None: no compression, only the other settings'=>'Keine: keine Komprimierung, nur die übrigen Einstellungen','No compression, only the other settings.'=>'Keine Komprimierung, nur die übrigen Einstellungen.','a language alt text is written inEnglish'=>'Englisch','a language alt text is written inSpanish'=>'Spanisch','a language alt text is written inFrench'=>'Französisch','a language alt text is written inGerman'=>'Deutsch','a language alt text is written inItalian'=>'Italienisch','a language alt text is written inPortuguese'=>'Portugiesisch','a language alt text is written inDutch'=>'Niederländisch','a language alt text is written inPolish'=>'Polnisch','a language alt text is written inSwedish'=>'Schwedisch','a language alt text is written inTurkish'=>'Türkisch','a language alt text is written inRussian'=>'Russisch','a language alt text is written inUkrainian'=>'Ukrainisch','a language alt text is written inArabic'=>'Arabisch','a language alt text is written inPersian'=>'Persisch','a language alt text is written inHebrew'=>'Hebräisch','a language alt text is written inHindi'=>'Hindi','a language alt text is written inIndonesian'=>'Indonesisch','a language alt text is written inVietnamese'=>'Vietnamesisch','a language alt text is written inThai'=>'Thailändisch','a language alt text is written inJapanese'=>'Japanisch','a language alt text is written inKorean'=>'Koreanisch','a language alt text is written inSimplified Chinese'=>'Vereinfachtes Chinesisch','a language alt text is written inTraditional Chinese'=>'Traditionelles Chinesisch','Iminify doesn\'t know this key. Check that you copied all of it, or make a new one.'=>'Iminify kennt diesen Schlüssel nicht. Prüfe, ob du ihn vollständig kopiert hast, oder erstelle einen neuen.','That is an API key. A site needs a site key: make one under Settings, Sites on iminify.com, or press Connect instead.'=>'Das ist ein API-Schlüssel. Eine Website braucht einen Website-Schlüssel: Erstelle einen unter „Settings › Sites“ auf iminify.com oder klicke stattdessen auf „Verbinden“.','This key belongs to the site at another address, so this copy of the site can\'t use it. Connect this copy as a site of its own, or move the connection here.'=>'Dieser Schlüssel gehört zur Website unter einer anderen Adresse, daher kann diese Kopie der Website ihn nicht verwenden. Verbinde diese Kopie als eigene Website oder verschiebe die Verbindung hierher.','Iminify asked the plugin to wait. Try again in %s.'=>'Iminify hat das Plugin gebeten zu warten. Versuche es in %s erneut.','Iminify asked the plugin to wait. Try again later.'=>'Iminify hat das Plugin gebeten zu warten. Versuche es später erneut.','The connection can no longer be used: it expired, was turned down, or was used already. Press Connect to start again.'=>'Die Verbindung kann nicht mehr verwendet werden: Sie ist abgelaufen, wurde abgelehnt oder wurde bereits verwendet. Klicke auf „Verbinden“, um neu zu beginnen.','AI alt text is off for this site. Turn it on in the plugin\'s settings first.'=>'KI-Alternativtexte sind für diese Website ausgeschaltet. Schalte sie zuerst in den Einstellungen des Plugins ein.','The audit scans only this site\'s own pages. Enter the address of a page on this site.'=>'Die Prüfung scannt nur die eigenen Seiten dieser Website. Gib die Adresse einer Seite dieser Website ein.','The network\'s key was made for a single site, so the network\'s sites can\'t join with it. A super admin connects the network again from the network admin.'=>'Der Schlüssel des Netzwerks wurde für eine einzelne Website erstellt, daher können die Websites des Netzwerks damit nicht beitreten. Ein Super-Administrator verbindet das Netzwerk über die Netzwerkverwaltung erneut.','The network already has as many sites as one network can hold. Remove a site you no longer use under Settings, Sites on iminify.com, or connect this site on its own.'=>'Das Netzwerk hat bereits so viele Websites, wie ein Netzwerk haben kann. Entferne unter „Settings › Sites“ auf iminify.com eine Website, die du nicht mehr nutzt, oder verbinde diese Website einzeln.','This site is already connected to the account on its own, or in another network. Disconnect it under Settings, Sites on iminify.com to add it to this network, or connect it here on its own.'=>'Diese Website ist bereits einzeln oder in einem anderen Netzwerk mit dem Konto verbunden. Trenne sie unter „Settings › Sites“ auf iminify.com, um sie diesem Netzwerk hinzuzufügen, oder verbinde sie hier einzeln.','This version of Iminify Image Optimizer is too old to keep optimizing images. Update it from the Plugins page.'=>'Diese Version von Iminify Image Optimizer ist zu alt, um weiter Bilder zu optimieren. Aktualisiere sie auf der Seite „Plugins“.','Your account\'s images for the day are used up. New uploads wait and go out by themselves when the next batch opens.'=>'Die Bilder deines Kontos für heute sind aufgebraucht. Neue Uploads warten und werden automatisch gesendet, sobald das nächste Kontingent freigegeben wird.','This site had its free trial of Pro on another Iminify account, so its uploads get the free plan\'s numbers here.'=>'Diese Website hatte ihre kostenlose Pro-Testphase bereits mit einem anderen Iminify-Konto, daher gelten für ihre Uploads hier die Werte des kostenlosen Tarifs.','The network isn\'t connected to Iminify. A super admin connects it from the network admin.'=>'Das Netzwerk ist nicht mit Iminify verbunden. Ein Super-Administrator verbindet es über die Netzwerkverwaltung.','This site is joining the network already. Wait a moment and look again.'=>'Diese Website tritt dem Netzwerk bereits bei. Warte einen Moment und sieh erneut nach.','WordPress couldn\'t store the site key. Press Join the network to try again.'=>'WordPress konnte den Website-Schlüssel nicht speichern. Klicke auf „Dem Netzwerk beitreten“, um es erneut zu versuchen.','The image couldn\'t be copied back from WP Offload Media\'s bucket to send it.'=>'Das Bild konnte zum Senden nicht aus dem Bucket von WP Offload Media zurückkopiert werden.','The uploads folder'=>'Der Uploads-Ordner','Name a folder inside wp-content, such as themes/your-theme.'=>'Nenne einen Ordner innerhalb von wp-content, etwa themes/your-theme.','There is no folder at that path inside wp-content.'=>'Unter diesem Pfad gibt es in wp-content keinen Ordner.','That folder is a link to another place, so Iminify leaves it out.'=>'Dieser Ordner ist ein Link auf einen anderen Ort, daher lässt Iminify ihn aus.','That\'s the media library\'s folder: its images are optimized from the media library.'=>'Das ist der Ordner der Mediathek: Seine Bilder werden über die Mediathek optimiert.','That\'s the Iminify plugin\'s own folder, which every update replaces.'=>'Das ist der eigene Ordner des Iminify-Plugins, den jedes Update ersetzt.','Other tools keep copies, caches or backups in that folder, so its images aren\'t the site\'s own.'=>'Andere Tools legen in diesem Ordner Kopien, Caches oder Backups ab, daher sind seine Bilder nicht die eigenen der Website.','That folder holds the media library\'s files or their backups, which Iminify handles from the media library.'=>'Dieser Ordner enthält die Dateien der Mediathek oder deren Backups, die Iminify über die Mediathek verarbeitet.','That folder holds hidden files or a project\'s dependencies, which Iminify leaves alone.'=>'Dieser Ordner enthält versteckte Dateien oder die Abhängigkeiten eines Projekts, die Iminify nicht anrührt.','On a network, other folders are chosen on the main site.'=>'In einem Netzwerk werden weitere Ordner auf der Hauptwebsite ausgewählt.','That folder is already in the list, inside %s.'=>'Dieser Ordner ist bereits in der Liste, innerhalb von %s.','The list holds as many folders as it can. Remove one, or choose the folder that holds several of them.'=>'Die Liste enthält bereits so viele Ordner wie möglich. Entferne einen oder wähle den Ordner, der mehrere davon enthält.','Update the Iminify plugin first.'=>'Aktualisiere zuerst das Iminify-Plugin.','Your account\'s images for the day are used up. The next batch opens on %s.'=>'Die Bilder deines Kontos für heute sind aufgebraucht. Das nächste Kontingent wird am %s freigegeben.','The server is low on disk space. Free some up, then optimize this image.'=>'Auf dem Server wird der Speicherplatz knapp. Gib etwas frei und optimiere dieses Bild dann.','No original of this image was kept, so it can\'t be optimized again.'=>'Von diesem Bild wurde kein Original behalten, daher kann es nicht erneut optimiert werden.','This image is too large to send: past your plan\'s file size, or more than this server\'s memory can hold.'=>'Dieses Bild ist zu groß zum Senden: über der Dateigröße deines Tarifs oder größer, als der Arbeitsspeicher dieses Servers fassen kann.','Not optimized: update the Iminify plugin first.'=>'Nicht optimiert: Aktualisiere zuerst das Iminify-Plugin.','Not sent: this server\'s PHP can\'t open zip files. Ask your host to turn on PHP\'s zip extension.'=>'Nicht gesendet: Das PHP dieses Servers kann keine ZIP-Dateien öffnen. Bitte deinen Hoster, die ZIP-Erweiterung von PHP zu aktivieren.','Not sent: no original of this image is left to make the optimized file from.'=>'Nicht gesendet: Von diesem Bild ist kein Original mehr übrig, aus dem die optimierte Datei erstellt werden könnte.','Not sent: this image is past your plan\'s file size, or more than this server\'s memory can hold.'=>'Nicht gesendet: Dieses Bild liegt über der Dateigröße deines Tarifs oder ist größer, als der Arbeitsspeicher dieses Servers fassen kann.','The image\'s file or its backup went missing while it was on its way.'=>'Die Datei des Bildes oder sein Backup ist verschwunden, während es unterwegs war.','Not written: the image is no longer in a folder Iminify optimizes.'=>'Nicht geschrieben: Das Bild liegt nicht mehr in einem Ordner, den Iminify optimiert.','Kept as it is: Iminify optimizes JPEG, PNG, WebP and GIF images.'=>'Unverändert belassen: Iminify optimiert JPEG-, PNG-, WebP- und GIF-Bilder.','The image couldn\'t be read.'=>'Das Bild konnte nicht gelesen werden.','Not sent: the image is no longer in a folder Iminify optimizes.'=>'Nicht gesendet: Das Bild liegt nicht mehr in einem Ordner, den Iminify optimiert.','Not sent: the image\'s file isn\'t there, or is a link to another place.'=>'Nicht gesendet: Die Datei des Bildes ist nicht vorhanden oder ist ein Link auf einen anderen Ort.','Kept as it is: this site leaves this image out.'=>'Unverändert belassen: Diese Website schließt dieses Bild aus.','Waiting for the next batch.'=>'Wartet auf das nächste Kontingent.','Waiting for the site to be connected to Iminify.'=>'Wartet darauf, dass die Website mit Iminify verbunden wird.','Not optimized: the server is low on disk space. Free some up, then optimize this image.'=>'Nicht optimiert: Auf dem Server wird der Speicherplatz knapp. Gib etwas frei und optimiere dieses Bild dann.','Iminify couldn\'t finish this image after several tries.'=>'Iminify konnte dieses Bild nach mehreren Versuchen nicht fertigstellen.','The original couldn\'t be put back, so the image stays as it was.'=>'Das Original konnte nicht wieder eingesetzt werden, daher bleibt das Bild, wie es war.','Iminify changed nothing in this image, so it already is as it was.'=>'Iminify hat an diesem Bild nichts geändert, daher ist es bereits im ursprünglichen Zustand.','This image has changed since Iminify optimized it, so its backup is no longer its original.'=>'Dieses Bild wurde geändert, seit Iminify es optimiert hat, daher ist sein Backup nicht mehr sein Original.','The image\'s file isn\'t there any more, or isn\'t in a folder Iminify optimizes.'=>'Die Datei des Bildes ist nicht mehr vorhanden oder liegt nicht in einem Ordner, den Iminify optimiert.','No original of this image was kept, so it can\'t be restored.'=>'Von diesem Bild wurde kein Original behalten, daher kann es nicht wiederhergestellt werden.','Changed since Iminify optimized it, so it can be optimized again.'=>'Seit der Optimierung durch Iminify geändert, daher kann es erneut optimiert werden.','This image already has alt text, or its text is on the way.'=>'Dieses Bild hat bereits einen Alternativtext, oder sein Text ist unterwegs.','The backup of this image couldn\'t be saved, so it wasn\'t optimized. Check that WordPress can write to the uploads folder, or turn backups off in the Iminify settings.'=>'Das Backup dieses Bildes konnte nicht gespeichert werden, daher wurde es nicht optimiert. Prüfe, ob WordPress in den Uploads-Ordner schreiben kann, oder schalte Backups in den Iminify-Einstellungen aus.','The image changed since its backup was made, and the old backup couldn\'t be moved aside, so it wasn\'t optimized.'=>'Das Bild wurde geändert, seit sein Backup erstellt wurde, und das alte Backup konnte nicht beiseitegelegt werden, daher wurde es nicht optimiert.','A bulk run is already going. Stop it first.'=>'Eine Massenoptimierung läuft bereits. Halte sie zuerst an.','The files in other folders are optimized, sent again or restored, all of them at once.'=>'Die Dateien in weiteren Ordnern werden alle auf einmal optimiert, erneut gesendet oder wiederhergestellt.','Iminify is still looking through your folders. Start again once it has finished.'=>'Iminify durchsucht deine Ordner noch. Starte erneut, sobald das abgeschlossen ist.','The server is low on disk space. Free some up, then start again.'=>'Auf dem Server wird der Speicherplatz knapp. Gib etwas frei und starte dann erneut.','Not optimized: the bulk run was stopped.'=>'Nicht optimiert: Die Massenoptimierung wurde angehalten.','Kept as uploaded: Iminify optimizes JPEG, PNG, WebP and GIF images.'=>'Belassen wie hochgeladen: Iminify optimiert JPEG-, PNG-, WebP- und GIF-Bilder.','Choose a folder first.'=>'Wähle zuerst einen Ordner.','No optimized file is left to restore in your folders.'=>'In deinen Ordnern ist keine optimierte Datei mehr zum Wiederherstellen übrig.','No file in your folders failed.'=>'In deinen Ordnern ist keine Datei fehlgeschlagen.','Every file in your folders is already optimized or on its way.'=>'Jede Datei in deinen Ordnern ist bereits optimiert oder unterwegs.','No optimized image is left to restore.'=>'Es ist kein optimiertes Bild mehr zum Wiederherstellen übrig.','No image another plugin optimized has an original left to optimize it again from.'=>'Kein von einem anderen Plugin optimiertes Bild hat noch ein Original, aus dem es erneut optimiert werden könnte.','Every image already has alt text, or its text is on the way.'=>'Jedes Bild hat bereits einen Alternativtext, oder sein Text ist unterwegs.','No optimized image lacks anything your site asks for now.'=>'Keinem optimierten Bild fehlt etwas, das deine Website jetzt verlangt.','Every image is already optimized or on its way.'=>'Jedes Bild ist bereits optimiert oder unterwegs.','Restored: the original is back.'=>'Wiederhergestellt: Das Original ist zurück.','The image isn\'t in the uploads folder.'=>'Das Bild liegt nicht im Uploads-Ordner.','Not optimized: the site isn\'t connected to Iminify.'=>'Nicht optimiert: Die Website ist nicht mit Iminify verbunden.','This image has changed since Iminify optimized it, so optimize it again instead.'=>'Dieses Bild wurde geändert, seit Iminify es optimiert hat, optimiere es daher stattdessen erneut.','This image lacks nothing your site asks for now.'=>'Diesem Bild fehlt nichts, was deine Website jetzt verlangt.','This image\'s original is too large to send: past your plan\'s file size, or more than this server\'s memory can hold.'=>'Das Original dieses Bildes ist zu groß zum Senden: über der Dateigröße deines Tarifs oder größer, als der Arbeitsspeicher dieses Servers fassen kann.','Not optimized: the site doesn\'t optimize uploads.'=>'Nicht optimiert: Die Website optimiert keine Uploads.','Not sent: this image\'s original is too large to send, past your plan\'s file size or more than this server\'s memory can hold.'=>'Nicht gesendet: Das Original dieses Bildes ist zu groß zum Senden, über der Dateigröße deines Tarifs oder größer, als der Arbeitsspeicher dieses Servers fassen kann.','Not sent: no original of this image is left to make the optimized files from.'=>'Nicht gesendet: Von diesem Bild ist kein Original mehr übrig, aus dem die optimierten Dateien erstellt werden könnten.','WordPress couldn\'t make the missing sizes of this image.'=>'WordPress konnte die fehlenden Größen dieses Bildes nicht erstellen.','Not sent: the image\'s file isn\'t in the uploads folder.'=>'Nicht gesendet: Die Datei des Bildes liegt nicht im Uploads-Ordner.','Its files are attachment #%d\'s, as a translation\'s are, so Iminify optimizes them there.'=>'Seine Dateien gehören zu Anhang #%d, wie bei einer Übersetzung, daher optimiert Iminify sie dort.','Kept as uploaded: this site leaves this image out.'=>'Belassen wie hochgeladen: Diese Website schließt dieses Bild aus.','The original couldn\'t be copied back from WP Offload Media\'s bucket, so the image stays as it was. Try again.'=>'Das Original konnte nicht aus dem Bucket von WP Offload Media zurückkopiert werden, daher bleibt das Bild, wie es war. Versuche es erneut.','WordPress couldn\'t read the original, so the image\'s sizes stay as they were. Try again.'=>'WordPress konnte das Original nicht lesen, daher bleiben die Größen des Bildes, wie sie waren. Versuche es erneut.','%s kept no original of this image that Iminify can check, so it can\'t be restored here.'=>'%s hat kein Original dieses Bildes behalten, das Iminify prüfen kann, daher kann es hier nicht wiederhergestellt werden.','Iminify hasn\'t changed this image, so there\'s nothing to restore.'=>'Iminify hat dieses Bild nicht verändert, daher gibt es nichts wiederherzustellen.','This image has changed since Iminify optimized it, so restoring it would overwrite the new one.'=>'Dieses Bild wurde geändert, seit Iminify es optimiert hat, daher würde eine Wiederherstellung das neue überschreiben.','No original of this image was kept, so it can\'t be restored. Backups were off when it was optimized, or the backup was deleted.'=>'Von diesem Bild wurde kein Original behalten, daher kann es nicht wiederhergestellt werden. Backups waren bei der Optimierung ausgeschaltet, oder das Backup wurde gelöscht.','The image couldn\'t be restored.'=>'Das Bild konnte nicht wiederhergestellt werden.','The image changed while Iminify was optimizing it, so it\'s sent again.'=>'Das Bild wurde geändert, während Iminify es optimiert hat, daher wird es erneut gesendet.','This server\'s PHP can\'t open zip files: ask your host to turn on PHP\'s zip extension.'=>'Das PHP dieses Servers kann keine ZIP-Dateien öffnen: Bitte deinen Hoster, die ZIP-Erweiterung von PHP zu aktivieren.','Iminify\'s download couldn\'t be opened.'=>'Der Download von Iminify konnte nicht geöffnet werden.','Deactivate Converter for Media, or turn off "Conversion of new images" in its General Settings, under Settings, Converter for Media.'=>'Deaktiviere Converter for Media oder schalte „Conversion of new images“ in dessen „General Settings“ unter Einstellungen › Converter for Media aus.','Deactivate Image Optimizer by Elementor, or turn off "Optimize new uploads" under Elementor, Image Optimization, Settings.'=>'Deaktiviere Image Optimizer by Elementor oder schalte „Optimize new uploads“ unter Elementor › Image Optimization › Settings aus.','Image Optimizer by Elementor converted this image, giving it a new address that your posts now link to, and kept its original beside it. Its own Restore puts the original back, with its address, while that plugin is installed; Iminify doesn\'t rewrite your posts, so it doesn\'t restore this image.'=>'Image Optimizer by Elementor hat dieses Bild konvertiert, ihm eine neue Adresse gegeben, auf die deine Beiträge jetzt verlinken, und sein Original daneben behalten. Mit seiner eigenen Wiederherstellung holt es das Original samt Adresse zurück, solange es installiert ist; Iminify schreibt deine Beiträge nicht um und stellt dieses Bild daher nicht wieder her.','Deactivate EWWW Image Optimizer.'=>'Deaktiviere EWWW Image Optimizer.','EWWW Image Optimizer kept this image\'s original on its own servers, for 30 days. Restore it in EWWW Image Optimizer while its key and those days last; Iminify can\'t fetch it.'=>'EWWW Image Optimizer hat das Original dieses Bildes 30 Tage lang auf seinen eigenen Servern aufbewahrt. Stelle es in EWWW Image Optimizer wieder her, solange dessen Schlüssel und diese Tage reichen; Iminify kann es nicht abrufen.','Deactivate Imagify, or turn off "Auto-Optimize images on upload" in its settings.'=>'Deaktiviere Imagify oder schalte „Auto-Optimize images on upload“ in dessen Einstellungen aus.','Those lines are gone already, or their plugin is on again.'=>'Diese Zeilen sind bereits entfernt, oder ihr Plugin ist wieder aktiv.','Only someone who can manage the network removes lines every site shares.'=>'Zeilen, die jede Website teilt, entfernt nur jemand, der das Netzwerk verwalten darf.','The plugin can’t take these lines out. Remove them by hand.'=>'Das Plugin kann diese Zeilen nicht entfernen. Entferne sie von Hand.','%s no longer uses them, yet they still answer a browser that reads WebP or AVIF with the copy it made of an image in its own folder, in place of the image, so a visitor can get a copy made before Iminify optimized it.'=>'%s verwendet sie nicht mehr, aber sie beantworten einen Browser, der WebP oder AVIF liest, weiterhin mit der Kopie, die es in seinem eigenen Ordner von einem Bild erstellt hat, anstelle des Bildes, sodass ein Besucher eine Kopie erhalten kann, die vor der Optimierung durch Iminify erstellt wurde.','%s no longer uses them, yet they still answer a browser that reads WebP or AVIF with whatever WebP or AVIF file is named after an image, however old, in place of the image, so a visitor can get a copy made before Iminify optimized it.'=>'%s verwendet sie nicht mehr, aber sie beantworten einen Browser, der WebP oder AVIF liest, weiterhin mit jeder WebP- oder AVIF-Datei, die nach einem Bild benannt ist, egal wie alt, anstelle des Bildes, sodass ein Besucher eine Kopie erhalten kann, die vor der Optimierung durch Iminify erstellt wurde.','Nginx keeps them until it is reloaded, so reload it once they are gone.'=>'Nginx behält sie, bis es neu geladen wird, lade es daher neu, sobald sie entfernt sind.','Smush added this rule for the PNG images it turned into JPEG, and it is still among WordPress’s rewrite rules: a request for such a PNG, no longer there, ends on your home page in place of a “not found” answer.'=>'Smush hat diese Regel für die PNG-Bilder hinzugefügt, die es in JPEG umgewandelt hat, und sie steht noch in den Umschreibungsregeln von WordPress: Eine Anfrage nach einem solchen PNG, das nicht mehr existiert, landet auf deiner Homepage statt bei einer „Nicht gefunden“-Antwort.','Turn off "Auto Request Cron" under LiteSpeed Cache, Image Optimization, and "Auto Rescale Original Images" under Page Optimization, Media Settings, and let the images it already sent come back, or deactivate LiteSpeed Cache.'=>'Schalte „Auto Request Cron“ unter LiteSpeed Cache › Image Optimization und „Auto Rescale Original Images“ unter Page Optimization › Media Settings aus und lass die bereits gesendeten Bilder zurückkommen, oder deaktiviere LiteSpeed Cache.','Deactivate Modern Image Formats: no setting of its own stops it.'=>'Deaktiviere Modern Image Formats: Keine eigene Einstellung hält es auf.','Modern Image Formats replaced this image\'s files with modern-format ones made from its original, which WordPress keeps. Putting the original back would change the image\'s addresses and break the posts that link to them, so Iminify doesn\'t restore it.'=>'Modern Image Formats hat die Dateien dieses Bildes durch Dateien in modernen Formaten ersetzt, die aus seinem Original erstellt wurden, das WordPress behält. Das Original wieder einzusetzen würde die Adressen des Bildes ändern und die Beiträge beschädigen, die darauf verlinken, daher stellt Iminify es nicht wieder her.','Deactivate Optimole, or choose "Optimole Cloud and your website" under Optimole, Settings, Image Storage.'=>'Deaktiviere Optimole oder wähle „Optimole Cloud and your website“ unter Optimole › Settings › Image Storage.','Optimole moved this image to its cloud and deleted its files here. Roll it back in Optimole first (it needs Optimole active and connected), and Iminify can optimize it then.'=>'Optimole hat dieses Bild in seine Cloud verschoben und seine Dateien hier gelöscht. Hole es zuerst in Optimole zurück (dafür muss Optimole aktiv und verbunden sein), dann kann Iminify es optimieren.','%1$s is active and optimizes your uploads itself, so Iminify optimizes nothing while it does, to keep any image from being compressed twice. %2$s'=>'%1$s ist aktiv und optimiert deine Uploads selbst, daher optimiert Iminify nichts, solange es das tut, damit kein Bild doppelt komprimiert wird. %2$s','Optimized by %s'=>'Optimiert von %s','Deactivate ShortPixel, or turn off "Optimize media on upload" in its settings, under Processing.'=>'Deaktiviere ShortPixel oder schalte „Optimize media on upload“ in dessen Einstellungen unter „Processing“ aus.','Deactivate Smush, or turn off "Automatic compression" in its settings.'=>'Deaktiviere Smush oder schalte „Automatic compression“ in dessen Einstellungen aus.','Deactivate TinyPNG, or set it to compress new images manually in its settings.'=>'Deaktiviere TinyPNG oder stelle in dessen Einstellungen ein, dass neue Bilder manuell komprimiert werden.','Iminify is scanning the page.'=>'Iminify scannt die Seite.','Your pages now get the missing width, height and alt text as they’re sent. Scan the page again to see it.'=>'Deine Seiten erhalten jetzt beim Ausliefern die fehlende Breite, Höhe und den fehlenden Alternativtext. Scanne die Seite erneut, um es zu sehen.','Every page, every week'=>'Jede Seite, jede Woche','A weekly check audits every page in your site\'s sitemap once a week, compresses the images that are new or changed, and emails you what it found. You set it up on iminify.com from a crawl of your site, where you can see which plans include it.'=>'Eine wöchentliche Prüfung prüft einmal pro Woche jede Seite in der Sitemap deiner Website, komprimiert die neuen oder geänderten Bilder und schickt dir per E-Mail, was sie gefunden hat. Du richtest sie auf iminify.com über einen Crawl deiner Website ein und siehst dort auch, welche Tarife sie enthalten.','Set up a weekly check'=>'Wöchentliche Prüfung einrichten','Couldn\'t read the page'=>'Seite nicht lesbar','Waiting to scan'=>'Wartet auf Scan','Scanning'=>'Wird gescannt','Done'=>'Fertig','No images'=>'Keine Bilder','Stopped'=>'Angehalten','Failed'=>'Fehlgeschlagen','On its way'=>'Unterwegs','Waiting'=>'Wartet','Iminify disconnected this site, so its pages can’t be audited. Connect it again to carry on.'=>'Iminify hat die Verbindung dieser Website getrennt, daher können ihre Seiten nicht geprüft werden. Verbinde sie erneut, um fortzufahren.','Connect this site to Iminify to audit its pages.'=>'Verbinde diese Website mit Iminify, um ihre Seiten zu prüfen.','Go to the settings'=>'Zu den Einstellungen','Scan a page'=>'Seite scannen','Iminify opens the page as a visitor would and measures every image it shows.'=>'Iminify öffnet die Seite wie ein Besucher und misst jedes angezeigte Bild.','Page'=>'Seite','Another address on this site'=>'Eine andere Adresse auf dieser Website','Address'=>'Adresse','Scan'=>'Scannen','You can scan again in %s second.'=>'Du kannst in %s Sekunde erneut scannen.' . "\0" . 'Du kannst in %s Sekunden erneut scannen.','%s page scan used today. Each audit counts as one.'=>'%s Seitenscan heute genutzt. Jede Prüfung zählt als einer.' . "\0" . '%s Seitenscans heute genutzt. Jede Prüfung zählt als einer.','%1$s of %2$s page scan left today. Each audit counts as one.'=>'%1$s von %2$s Seitenscan heute übrig. Jede Prüfung zählt als einer.' . "\0" . '%1$s von %2$s Seitenscans heute übrig. Jede Prüfung zählt als einer.','Your page scans for today are used up. More come on %s.'=>'Deine Seitenscans für heute sind aufgebraucht. Neue gibt es am %s.','Your page scans for today are used up.'=>'Deine Seitenscans für heute sind aufgebraucht.','Recent audits'=>'Letzte Prüfungen','Images on the page'=>'Bilder auf der Seite','Choose a page and press Scan. Iminify lists every image on it, each beside the image in your library it is, with what is worth fixing.'=>'Wähle eine Seite und klicke auf „Scannen“. Iminify listet jedes Bild darauf auf, jeweils neben dem zugehörigen Bild aus deiner Mediathek, mit allem, was sich zu verbessern lohnt.','Iminify is opening the page and measuring its images. This usually takes less than a minute, and the page shows them as soon as they’re in.'=>'Iminify öffnet die Seite und misst ihre Bilder. Das dauert meist weniger als eine Minute, und die Seite zeigt sie an, sobald sie da sind.','The page showed no images.'=>'Die Seite hat keine Bilder angezeigt.','%1$s image on the page, %2$s with something to fix.'=>'%1$s Bild auf der Seite, %2$s mit Verbesserungsbedarf.' . "\0" . '%1$s Bilder auf der Seite, %2$s mit Verbesserungsbedarf.','Nothing to fix: every image on this page is sized, loaded and described well.'=>'Kein Verbesserungsbedarf: Jedes Bild auf dieser Seite ist passend dimensioniert, geladen und beschrieben.','Hide the images with nothing to fix'=>'Bilder ohne Verbesserungsbedarf ausblenden','Show %s image with nothing to fix'=>'%s Bild ohne Verbesserungsbedarf anzeigen' . "\0" . '%s Bilder ohne Verbesserungsbedarf anzeigen','%s image from your media library is on this page without its width and height, or without the alt text it has in the library. The plugin can add what’s missing to your pages as they’re sent, from the library.'=>'%s Bild aus deiner Mediathek ist auf dieser Seite ohne seine Breite und Höhe oder ohne den Alternativtext, den es in der Mediathek hat. Das Plugin kann das Fehlende beim Ausliefern deiner Seiten aus der Mediathek ergänzen.' . "\0" . '%s Bilder aus deiner Mediathek sind auf dieser Seite ohne ihre Breite und Höhe oder ohne den Alternativtext, den sie in der Mediathek haben. Das Plugin kann das Fehlende beim Ausliefern deiner Seiten aus der Mediathek ergänzen.','Fill them in on every page'=>'Auf jeder Seite ergänzen','Someone who can change the plugin’s settings can turn this on.'=>'Jemand, der die Einstellungen des Plugins ändern darf, kann das einschalten.','Use the %1$s size (%2$s × %3$s) where this image is placed. The page’s editor doesn’t hold it: your theme, a template or a widget shows it, and the size is chosen there.'=>'Verwende die Größe %1$s (%2$s × %3$s) dort, wo dieses Bild platziert ist. Der Editor der Seite enthält es nicht: Dein Theme, ein Template oder ein Widget zeigt es an, und die Größe wird dort gewählt.','Use the %1$s size (%2$s × %3$s) here: in the editor, select the image and choose it under Resolution.'=>'Verwende hier die Größe %1$s (%2$s × %3$s): Wähle im Editor das Bild aus und wähle die Größe unter „Auflösung“.','Edit the page'=>'Seite bearbeiten','The plugin adds them as the page is sent. Scan again to see it.'=>'Das Plugin ergänzt sie beim Ausliefern der Seite. Scanne erneut, um es zu sehen.','Iminify is writing the image’s alt text. Scan again once it’s in.'=>'Iminify schreibt den Alternativtext des Bildes. Scanne erneut, sobald er da ist.','Iminify can write it once AI alt text is on for this site.'=>'Iminify kann ihn schreiben, sobald KI-Alternativtexte für diese Website eingeschaltet sind.','Turn it on in the settings'=>'In den Einstellungen einschalten','Its alt text is on its way. Scan again once it’s in.'=>'Sein Alternativtext ist unterwegs. Scanne erneut, sobald er da ist.','Translations share this image, each with an alt text in its own language: write it on the one this page shows, in its edit screen.'=>'Übersetzungen teilen sich dieses Bild, jede mit einem Alternativtext in ihrer eigenen Sprache: Schreibe ihn bei der Übersetzung, die diese Seite zeigt, auf deren Bearbeitungsseite.','The plugin adds the alt text the image has in the media library as the page is sent. Scan again to see it.'=>'Das Plugin ergänzt beim Ausliefern der Seite den Alternativtext, den das Bild in der Mediathek hat. Scanne erneut, um es zu sehen.','(no title)'=>'(kein Titel)','%1$s, %2$s × %3$s'=>'%1$s, %2$s × %3$s','%s copy'=>'%s-Kopie','Largest in the first screen'=>'Größtes im ersten Bildschirm','shown at %1$s × %2$s'=>'angezeigt mit %1$s × %2$s','The image is on its way to Iminify.'=>'Das Bild ist unterwegs zu Iminify.','Copied'=>'Kopiert','Copy'=>'Kopieren','Cancel'=>'Abbrechen','(opens in a new tab)'=>'(öffnet in neuem Tab)','Loading…'=>'Wird geladen …','Try again'=>'Erneut versuchen','Dismiss'=>'Verwerfen','Iminify says your account\'s images for the day are still used up.'=>'Iminify meldet, dass die Bilder deines Kontos für heute weiterhin aufgebraucht sind.','On their way'=>'Unterwegs','Skipped'=>'Übersprungen','Restored'=>'Wiederhergestellt','Your library'=>'Deine Mediathek','%s image'=>'%s Bild' . "\0" . '%s Bilder','Your media library has no images yet.'=>'Deine Mediathek enthält noch keine Bilder.','optimized'=>'optimiert','Saved so far'=>'Bisher eingespart','of %1$s, %2$s%% less'=>'von %1$s, %2$s %% weniger','%1$s optimized %2$s image, with its original kept. Iminify leaves it as it is.'=>'%1$s hat %2$s Bild optimiert und sein Original behalten. Iminify lässt es unverändert.' . "\0" . '%1$s hat %2$s Bilder optimiert und jeweils das Original behalten. Iminify lässt sie unverändert.','%1$s optimized %2$s image, and kept no original of it. Iminify leaves it as it is.'=>'%1$s hat %2$s Bild optimiert und kein Original davon behalten. Iminify lässt es unverändert.' . "\0" . '%1$s hat %2$s Bilder optimiert und keine Originale davon behalten. Iminify lässt sie unverändert.','%1$s optimized %2$s images, %3$s of them with an original kept. Iminify leaves them as they are.'=>'%1$s hat %2$s Bilder optimiert und bei %3$s davon das Original behalten. Iminify lässt sie unverändert.','Finished'=>'Abgeschlossen','Paused: low disk'=>'Pausiert: Speicher knapp','Paused'=>'Pausiert','Waiting for another optimizer'=>'Wartet auf anderen Optimierer','Not moving'=>'Steht still','Waiting for the site'=>'Wartet auf die Website','Used up for today'=>'Für heute aufgebraucht','Iminify is busy'=>'Iminify ist ausgelastet','Restoring'=>'Wird wiederhergestellt','Running on this page'=>'Läuft auf dieser Seite','Running'=>'Läuft','Other folders restored'=>'Weitere Ordner wiederhergestellt','Restoring other folders'=>'Weitere Ordner werden wiederhergestellt','Other folders optimized'=>'Weitere Ordner optimiert','Optimizing other folders'=>'Weitere Ordner werden optimiert','Library restored'=>'Mediathek wiederhergestellt','Alt text written'=>'Alternativtexte geschrieben','Writing alt text'=>'Alternativtexte werden geschrieben','Missing formats made'=>'Fehlende Formate erstellt','Making the missing formats'=>'Fehlende Formate werden erstellt','Missing sizes made'=>'Fehlende Größen erstellt','Making the missing sizes'=>'Fehlende Größen werden erstellt','Optimized again from the originals'=>'Erneut aus den Originalen optimiert','Optimizing again from the originals'=>'Wird erneut aus den Originalen optimiert','Bulk optimization'=>'Massenoptimierung','Restored %1$s of %2$s image.'=>'%1$s von %2$s Bild wiederhergestellt.' . "\0" . '%1$s von %2$s Bildern wiederhergestellt.','Sent %1$s of %2$s image to Iminify.'=>'%1$s von %2$s Bild an Iminify gesendet.' . "\0" . '%1$s von %2$s Bildern an Iminify gesendet.','%s alt text on its way'=>'%s Alternativtext unterwegs' . "\0" . '%s Alternativtexte unterwegs','%s image with Iminify now'=>'%s Bild jetzt bei Iminify' . "\0" . '%s Bilder jetzt bei Iminify','image restored'=>'Bild wiederhergestellt' . "\0" . 'Bilder wiederhergestellt','image sent to Iminify'=>'Bild an Iminify gesendet' . "\0" . 'Bilder an Iminify gesendet','%d image couldn\'t be restored. Its row under Media, Other Folders says why.'=>'%d Bild konnte nicht wiederhergestellt werden. Seine Zeile unter Medien › Weitere Ordner nennt den Grund.' . "\0" . '%d Bilder konnten nicht wiederhergestellt werden. Ihre Zeilen unter Medien › Weitere Ordner nennen den Grund.','%d image couldn\'t be restored. Its panel in the media library says why.'=>'%d Bild konnte nicht wiederhergestellt werden. Sein Panel in der Mediathek nennt den Grund.' . "\0" . '%d Bilder konnten nicht wiederhergestellt werden. Ihre Panels in der Mediathek nennen den Grund.','Start now'=>'Jetzt starten','Pause'=>'Pausieren','Resume'=>'Fortsetzen','Stop'=>'Anhalten','Run it in the background instead'=>'Stattdessen im Hintergrund ausführen','Finished: the images are back as they were uploaded.'=>'Abgeschlossen: Die Bilder sind wieder so, wie sie hochgeladen wurden.','Finished: each image shows how its alt text came out in the media library.'=>'Abgeschlossen: Jedes Bild zeigt in der Mediathek, wie sein Alternativtext ausgefallen ist.','Finished: no image needed sending.'=>'Abgeschlossen: Kein Bild musste gesendet werden.','Finished: every image was sent. Each one shows how it came out in the media library.'=>'Abgeschlossen: Jedes Bild wurde gesendet. Jedes zeigt in der Mediathek, wie es ausgefallen ist.','Stopped. Images already with Iminify finish while this page is open; the rest stay as they are.'=>'Angehalten. Bilder, die bereits bei Iminify sind, werden fertiggestellt, solange diese Seite geöffnet ist; die übrigen bleiben unverändert.','Stopped. Images already with Iminify finish; the rest stay as they are.'=>'Angehalten. Bilder, die bereits bei Iminify sind, werden fertiggestellt; die übrigen bleiben unverändert.','Paused: the server is low on disk space. Free some up, then resume.'=>'Pausiert: Auf dem Server wird der Speicherplatz knapp. Gib etwas frei und setze dann fort.','Paused while the plugin was turned off.'=>'Pausiert, während das Plugin deaktiviert war.','Paused. Images already with Iminify finish while this page is open.'=>'Pausiert. Bilder, die bereits bei Iminify sind, werden fertiggestellt, solange diese Seite geöffnet ist.','Paused. Images already with Iminify finish.'=>'Pausiert. Bilder, die bereits bei Iminify sind, werden fertiggestellt.','Held while another image optimizer acts on your uploads. The run goes on by itself once it is switched off.'=>'Wartet, solange ein anderer Bildoptimierer deine Uploads bearbeitet. Der Durchlauf geht automatisch weiter, sobald dieser ausgeschaltet ist.','The run hasn\'t moved for a while: this site\'s scheduled tasks don\'t seem to run.'=>'Der Durchlauf kommt seit einer Weile nicht voran: Die geplanten Aufgaben dieser Website scheinen nicht zu laufen.','Your account\'s images for the day are used up. The run goes on by itself when the next batch opens on %s.'=>'Die Bilder deines Kontos für heute sind aufgebraucht. Der Durchlauf geht automatisch weiter, wenn am %s das nächste Kontingent freigegeben wird.','Held: Iminify isn\'t accepting this site\'s key. The run goes on by itself once the connection works.'=>'Wartet: Iminify akzeptiert den Schlüssel dieser Website nicht. Der Durchlauf geht automatisch weiter, sobald die Verbindung funktioniert.','Your account\'s AI alt texts for the day are used up. The run goes on by itself at %s.'=>'Die KI-Alternativtexte deines Kontos für heute sind aufgebraucht. Der Durchlauf geht am %s automatisch weiter.','Iminify is busy with the images already sent. The run sends more at %s.'=>'Iminify ist mit den bereits gesendeten Bildern beschäftigt. Der Durchlauf sendet am %s weitere.','Keep this page open: the images go out while it is.'=>'Lass diese Seite geöffnet: Die Bilder werden gesendet, solange sie offen ist.','The run goes on in the background, so you can leave this page.'=>'Der Durchlauf geht im Hintergrund weiter, du kannst diese Seite also verlassen.','Site Health says: %s'=>'Website-Zustand meldet: %s','If this site asks for a password before it opens, put that user name and password in wp-config.php so its scheduled tasks can reach it:'=>'Wenn diese Website vor dem Öffnen ein Passwort verlangt, trage diesen Benutzernamen und dieses Passwort in wp-config.php ein, damit ihre geplanten Aufgaben sie erreichen können:','Run it while this page is open instead, or carry it on from the shell:'=>'Führe ihn stattdessen aus, während diese Seite geöffnet ist, oder setze ihn über die Kommandozeile fort:','Run it while this page is open'=>'Ausführen, während diese Seite geöffnet ist','Compare the plans'=>'Tarife vergleichen','Connect this site to Iminify to optimize its images.'=>'Verbinde diese Website mit Iminify, um ihre Bilder zu optimieren.','The server is low on disk space, so nothing is optimized until some is freed.'=>'Auf dem Server wird der Speicherplatz knapp, daher wird nichts optimiert, bis wieder Platz frei ist.','Optimize the library'=>'Mediathek optimieren','%s image is not optimized yet.'=>'%s Bild ist noch nicht optimiert.' . "\0" . '%s Bilder sind noch nicht optimiert.','Their backups need about %1$s of disk space (%2$s free).'=>'Die Backups dafür benötigen etwa %1$s Speicherplatz (%2$s frei).','Their backups need about %s of disk space.'=>'Die Backups dafür benötigen etwa %s Speicherplatz.','Send the %s failed image again'=>'Das %s fehlgeschlagene Bild erneut senden' . "\0" . 'Die %s fehlgeschlagenen Bilder erneut senden','Nothing to optimize yet.'=>'Noch nichts zu optimieren.','Every image is optimized or on its way.'=>'Jedes Bild ist optimiert oder unterwegs.','No image is waiting to be optimized.'=>'Kein Bild wartet auf die Optimierung.','%s image was restored, and stays as it is: a run never takes an image someone put back. Optimize it again from its panel in the media library.'=>'%s Bild wurde wiederhergestellt und bleibt unverändert: Ein Durchlauf übernimmt nie ein Bild, das jemand zurückgesetzt hat. Optimiere es über sein Panel in der Mediathek erneut.' . "\0" . '%s Bilder wurden wiederhergestellt und bleiben unverändert: Ein Durchlauf übernimmt nie ein Bild, das jemand zurückgesetzt hat. Optimiere einzelne davon über ihr Panel in der Mediathek erneut.','Missing files'=>'Fehlende Dateien','%s optimized image lacks a format your site asks for now.'=>'%s optimiertem Bild fehlt ein Format, das deine Website jetzt verlangt.' . "\0" . '%s optimierten Bildern fehlt ein Format, das deine Website jetzt verlangt.','%s optimized image may lack a size your site makes now.'=>'%s optimiertem Bild fehlt möglicherweise eine Größe, die deine Website jetzt erstellt.' . "\0" . '%s optimierten Bildern fehlt möglicherweise eine Größe, die deine Website jetzt erstellt.','Alt text'=>'Alternativtext','%s image has no alt text.'=>'%s Bild hat keinen Alternativtext.' . "\0" . '%s Bilder haben keinen Alternativtext.','Send a small copy of each of these images to write its alt text? Each counts as one of your AI alt texts for the day, and an alt text someone wrote is never replaced.'=>'Eine verkleinerte Version jedes dieser Bilder senden, um seinen Alternativtext zu schreiben? Jedes zählt als einer deiner KI-Alternativtexte für heute, und ein Alternativtext, den jemand geschrieben hat, wird nie ersetzt.','%s AI alt texts left today.'=>'Heute noch %s KI-Alternativtexte übrig.','Send these images again to make what they lack? Each counts as one more image, and keeps its other files unless Iminify makes them smaller.'=>'Diese Bilder erneut senden, um das Fehlende zu erstellen? Jedes zählt als ein weiteres Bild und behält seine übrigen Dateien, sofern Iminify sie nicht verkleinert.','Optimize them again from their originals'=>'Erneut aus ihren Originalen optimieren','%s image another plugin optimized kept its original. Iminify can optimize it again from that original and keep its own backup of it. The original goes back first, unless the image was converted to WebP or AVIF: then its files are made again in that format, under the same names.'=>'%s von einem anderen Plugin optimiertes Bild hat sein Original behalten. Iminify kann es aus diesem Original erneut optimieren und ein eigenes Backup davon behalten. Zuerst wird das Original wieder eingesetzt, außer das Bild wurde in WebP oder AVIF konvertiert: Dann werden seine Dateien in diesem Format unter denselben Namen neu erstellt.' . "\0" . '%s von anderen Plugins optimierte Bilder haben ihre Originale behalten. Iminify kann sie aus diesen Originalen erneut optimieren und von jedem ein eigenes Backup behalten. Zuerst wird jedes Original wieder eingesetzt, außer das Bild wurde in WebP oder AVIF konvertiert: Dann werden seine Dateien in diesem Format unter denselben Namen neu erstellt.','Optimize these images again from their originals? Each counts as one more image, and one whose original only its plugin can put back is left as it is.'=>'Diese Bilder erneut aus ihren Originalen optimieren? Jedes zählt als ein weiteres Bild, und eines, dessen Original nur sein Plugin zurückholen kann, bleibt unverändert.','LiteSpeed Cache is active. Whenever WordPress makes an image\'s sizes again (Regenerate Thumbnails, or replacing an image), it deletes the WebP and AVIF copies beside it and puts back the old files it kept of an image it optimized, so Iminify reads that image as changed. "Remove Original Image Backups", under LiteSpeed Cache, Image Optimization, stops it putting old files back.'=>'LiteSpeed Cache ist aktiv. Immer wenn WordPress die Größen eines Bildes neu erstellt (Regenerate Thumbnails oder beim Ersetzen eines Bildes), löscht LiteSpeed Cache die WebP- und AVIF-Kopien daneben und setzt die alten Dateien wieder ein, die es von einem von ihm optimierten Bild behalten hat, sodass Iminify dieses Bild als geändert erkennt. „Remove Original Image Backups“ unter LiteSpeed Cache › Image Optimization verhindert, dass es alte Dateien wieder einsetzt.','In the background'=>'Im Hintergrund','So you can leave this page.'=>'Damit du diese Seite verlassen kannst.','While this page is open'=>'Solange diese Seite geöffnet ist','For a host whose scheduled tasks don\'t run.'=>'Für Hoster, bei denen geplante Aufgaben nicht laufen.','Run it'=>'Ausführen','Your plan'=>'Dein Tarif','all today'=>'alle heute','about %d day'=>'etwa %d Tag' . "\0" . 'etwa %d Tage','Your plan\'s daily images cover them all today.'=>'Die täglichen Bilder deines Tarifs reichen heute für alle.','The run goes on by itself each day.'=>'Der Durchlauf geht jeden Tag automatisch weiter.','See the plans'=>'Tarife ansehen','Other folders'=>'Weitere Ordner','Optimize the images in your theme and other folders outside the media library, where they are, with a backup of each.'=>'Optimiere die Bilder in deinem Theme und in anderen Ordnern außerhalb der Mediathek dort, wo sie liegen, mit einem Backup von jedem.','%1$s image in your folders: %2$s optimized, %3$s not yet.'=>'%1$s Bild in deinen Ordnern: %2$s optimiert, %3$s noch nicht.' . "\0" . '%1$s Bilder in deinen Ordnern: %2$s optimiert, %3$s noch nicht.','Iminify is still looking through them.'=>'Iminify durchsucht sie noch.','Put every optimized image in your folders back as it was? Their WebP and AVIF copies are deleted; the backups stay.'=>'Jedes optimierte Bild in deinen Ordnern wieder in den ursprünglichen Zustand zurücksetzen? Die WebP- und AVIF-Kopien werden gelöscht; die Backups bleiben.','Restore all'=>'Alle wiederherstellen','See the images'=>'Bilder ansehen','Optimize them'=>'Bilder optimieren','Send the failed again'=>'Fehlgeschlagene erneut senden','Choose folders'=>'Ordner auswählen','Restore the library'=>'Mediathek wiederherstellen','Put every optimized image back as it was uploaded, from its backup, with its sizes made again by WordPress. Do this before removing the plugin if you want your originals back in place. An image another plugin converted to WebP or AVIF stays as it is, since only that plugin can put its original back.'=>'Setze jedes optimierte Bild aus seinem Backup wieder so zurück, wie es hochgeladen wurde, und lass WordPress seine Größen neu erstellen. Tu das, bevor du das Plugin entfernst, wenn du deine Originale zurückhaben möchtest. Ein Bild, das ein anderes Plugin in WebP oder AVIF konvertiert hat, bleibt unverändert, da nur dieses Plugin sein Original zurückholen kann.','Put every optimized image back as it was uploaded? Their WebP and AVIF copies are deleted; the backups stay.'=>'Jedes optimierte Bild wieder so zurücksetzen, wie es hochgeladen wurde? Die WebP- und AVIF-Kopien werden gelöscht; die Backups bleiben.','Sent to Iminify.'=>'An Iminify gesendet.','The original is back.'=>'Das Original ist zurück.','Looking'=>'Wird durchsucht','Folders'=>'Ordner','Choose your theme or any folder in wp-content, and Iminify optimizes the images in it where they are, keeping a backup of each.'=>'Wähle dein Theme oder einen beliebigen Ordner in wp-content, und Iminify optimiert die Bilder darin dort, wo sie liegen, mit einem Backup von jedem.','Remove'=>'Entfernen','Your theme'=>'Dein Theme','Its parent theme'=>'Das übergeordnete Theme','Add your theme, %s'=>'Dein Theme hinzufügen, %s','Add its parent theme, %s'=>'Übergeordnetes Theme hinzufügen, %s','Add'=>'Hinzufügen','Another folder in wp-content'=>'Ein anderer Ordner in wp-content','Last looked on %1$s: %2$s images, %3$s new, %4$s changed.'=>'Zuletzt durchsucht am %1$s: %2$s Bilder, %3$s neu, %4$s geändert.','Iminify looks again after a theme or plugin update. Look now after changing images by hand.'=>'Iminify sucht nach jedem Theme- oder Plugin-Update erneut. Suche jetzt, wenn du Bilder von Hand geändert hast.','Look for new and changed images'=>'Nach neuen und geänderten Bildern suchen','In your folders'=>'In deinen Ordnern','A bulk run over these images is going on the bulk page.'=>'Auf der Seite Massenoptimierung läuft gerade ein Durchlauf über diese Bilder.','Optimize or restore them all on the bulk page.'=>'Auf der Seite Massenoptimierung kannst du sie alle optimieren oder wiederherstellen.','Go to Bulk Optimization'=>'Zur Massenoptimierung','Waiting to connect'=>'Wartet auf Verbindung','All'=>'Alle','Images'=>'Bilder','Add a folder to see its images here.'=>'Füge einen Ordner hinzu, um seine Bilder hier zu sehen.','No images were found in these folders.'=>'In diesen Ordnern wurden keine Bilder gefunden.','No image here.'=>'Hier ist kein Bild.','Previous'=>'Zurück','Page %1$s of %2$s'=>'Seite %1$s von %2$s','Next'=>'Weiter','%s%% smaller'=>'%s %% kleiner','Restore'=>'Wiederherstellen','Put the original back? Its WebP and AVIF copies are deleted; the backup stays.'=>'Das Original wieder einsetzen? Seine WebP- und AVIF-Kopien werden gelöscht; das Backup bleibt.','Disconnect the network from Iminify? Every key its sites joined with stops too, and new uploads on those sites stop being optimized. Images already optimized stay as they are.'=>'Die Verbindung des Netzwerks zu Iminify trennen? Jeder Schlüssel, mit dem seine Websites beigetreten sind, wird ebenfalls ungültig, und neue Uploads auf diesen Websites werden nicht mehr optimiert. Bereits optimierte Bilder bleiben unverändert.','Disconnect this site from Iminify? New uploads stop being optimized, and the site doesn\'t join the network again by itself: press Join the network to bring it back. Images already optimized stay as they are.'=>'Die Verbindung dieser Website zu Iminify trennen? Neue Uploads werden nicht mehr optimiert, und die Website tritt dem Netzwerk nicht automatisch wieder bei: Klicke auf „Dem Netzwerk beitreten“, um sie zurückzuholen. Bereits optimierte Bilder bleiben unverändert.','Disconnect this site from Iminify? New uploads stop being optimized. Images already optimized stay as they are.'=>'Die Verbindung dieser Website zu Iminify trennen? Neue Uploads werden nicht mehr optimiert. Bereits optimierte Bilder bleiben unverändert.','Disconnect'=>'Trennen','%1$s used, %2$s left'=>'%1$s genutzt, %2$s übrig','%s used, no daily limit'=>'%s genutzt, kein Tageslimit','%1$s, at %2$s, is connected to Iminify as a multisite network.'=>'%1$s unter %2$s ist als Multisite-Netzwerk mit Iminify verbunden.','%1$s, at %2$s, is connected to Iminify through its network.'=>'%1$s unter %2$s ist über sein Netzwerk mit Iminify verbunden.','%1$s, at %2$s, is connected to Iminify.'=>'%1$s unter %2$s ist mit Iminify verbunden.','Your account'=>'Dein Konto','Plan'=>'Tarif','%1$s, until %2$s'=>'%1$s, bis %2$s','Next batch'=>'Nächstes Kontingent','Network\'s sites'=>'Websites des Netzwerks','%1$s of %2$s'=>'%1$s von %2$s','The main site'=>'Die Hauptwebsite','%s saved'=>'%s eingespart','This site\'s Iminify account is set in wp-config.php.'=>'Das Iminify-Konto dieser Website ist in wp-config.php festgelegt.','Your plan on iminify.com'=>'Dein Tarif auf iminify.com','The network\'s key is set in wp-config.php as <code>IMINIFY_API_KEY</code>. To disconnect, remove it there, and disconnect the network under Settings, Sites on iminify.com.'=>'Der Schlüssel des Netzwerks ist in wp-config.php als <code>IMINIFY_API_KEY</code> festgelegt. Um die Verbindung zu trennen, entferne ihn dort und trenne das Netzwerk unter „Settings › Sites“ auf iminify.com.','The site\'s key is set in wp-config.php as <code>IMINIFY_API_KEY</code>. To disconnect, remove it there, and disconnect the site under Settings, Sites on iminify.com.'=>'Der Schlüssel der Website ist in wp-config.php als <code>IMINIFY_API_KEY</code> festgelegt. Um die Verbindung zu trennen, entferne ihn dort und trenne die Website unter „Settings › Sites“ auf iminify.com.','Waiting for your approval'=>'Wartet auf deine Freigabe','Needs attention'=>'Erfordert Aufmerksamkeit','The network is connected.'=>'Das Netzwerk ist verbunden.','The site is connected.'=>'Die Website ist verbunden.','The connection wasn\'t approved in time, or was turned down. Press Connect to try again.'=>'Die Verbindung wurde nicht rechtzeitig freigegeben oder wurde abgelehnt. Klicke auf „Verbinden“, um es erneut zu versuchen.','The network is disconnected here, but its key couldn\'t be stopped on Iminify. Disconnect it under Settings, Sites on iminify.com too.'=>'Die Verbindung des Netzwerks ist hier getrennt, aber sein Schlüssel konnte bei Iminify nicht gesperrt werden. Trenne es zusätzlich unter „Settings › Sites“ auf iminify.com.','The site is disconnected here, but its key couldn\'t be stopped on Iminify. Disconnect it under Settings, Sites on iminify.com too.'=>'Die Verbindung der Website ist hier getrennt, aber ihr Schlüssel konnte bei Iminify nicht gesperrt werden. Trenne sie zusätzlich unter „Settings › Sites“ auf iminify.com.','This site now uses %s’s settings.'=>'Diese Website verwendet jetzt die Einstellungen von %s.','The site joined the network.'=>'Die Website ist dem Netzwerk beigetreten.','Move the connection here'=>'Verbindung hierher verschieben','Connect this copy as its own site'=>'Diese Kopie als eigene Website verbinden','The lines are removed. Reload Nginx so it stops serving them.'=>'Die Zeilen wurden entfernt. Lade Nginx neu, damit es sie nicht mehr anwendet.','The lines are removed.'=>'Die Zeilen wurden entfernt.','Settings saved.'=>'Die Einstellungen wurden gespeichert.','The images waiting are on their way.'=>'Die wartenden Bilder sind unterwegs.','Your account\'s images for the day are still used up.'=>'Die Bilder deines Kontos für heute sind weiterhin aufgebraucht.','Iminify disconnected the network, so new uploads on its sites aren\'t optimized. Connect it again to carry on.'=>'Iminify hat die Verbindung des Netzwerks getrennt, daher werden neue Uploads auf seinen Websites nicht optimiert. Verbinde es erneut, um fortzufahren.','Iminify disconnected the network, so new uploads aren\'t optimized. A super admin connects it again in the network admin.'=>'Iminify hat die Verbindung des Netzwerks getrennt, daher werden neue Uploads nicht optimiert. Ein Super-Administrator verbindet es in der Netzwerkverwaltung erneut.','Iminify disconnected this site, so new uploads aren\'t optimized. Join the network again, or connect the site on its own, to carry on.'=>'Iminify hat die Verbindung dieser Website getrennt, daher werden neue Uploads nicht optimiert. Tritt dem Netzwerk erneut bei oder verbinde die Website einzeln, um fortzufahren.','Iminify disconnected this site, so new uploads aren\'t optimized. Connect it again to carry on.'=>'Iminify hat die Verbindung dieser Website getrennt, daher werden neue Uploads nicht optimiert. Verbinde sie erneut, um fortzufahren.','Connect your network'=>'Verbinde dein Netzwerk','Iminify compresses the images uploaded to every site of this network and makes WebP and AVIF copies of them. Connect the network to your Iminify account once, or create a free account on the way, and each site joins by itself the first time it needs Iminify.'=>'Iminify komprimiert die auf jede Website dieses Netzwerks hochgeladenen Bilder und erstellt WebP- und AVIF-Kopien davon. Verbinde das Netzwerk einmal mit deinem Iminify-Konto oder erstelle dabei ein kostenloses Konto, und jede Website tritt automatisch bei, sobald sie Iminify zum ersten Mal braucht.','Nothing is sent to Iminify until you connect. Connect opens iminify.com in a new tab, where you approve the network.'=>'Bis du verbindest, wird nichts an Iminify gesendet. „Netzwerk verbinden“ öffnet iminify.com in einem neuen Tab, wo du das Netzwerk freigibst.','Connect the network'=>'Netzwerk verbinden','Connect this site on its own'=>'Diese Website einzeln verbinden','This site can connect to an Iminify account of its own instead, and then never uses the network\'s connection.'=>'Diese Website kann sich stattdessen mit einem eigenen Iminify-Konto verbinden und nutzt dann nie die Verbindung des Netzwerks.','Connect opens iminify.com in a new tab, where you approve this site.'=>'„Verbinden“ öffnet iminify.com in einem neuen Tab, wo du diese Website freigibst.','Connect your site'=>'Verbinde deine Website','Iminify compresses the images you upload and makes WebP and AVIF copies of them. Connect this site to your Iminify account, or create a free account on the way, to start.'=>'Iminify komprimiert die Bilder, die du hochlädst, und erstellt WebP- und AVIF-Kopien davon. Verbinde diese Website mit deinem Iminify-Konto oder erstelle dabei ein kostenloses Konto, um zu beginnen.','Nothing is sent to Iminify until you connect. Connect opens iminify.com in a new tab, where you approve this site.'=>'Bis du verbindest, wird nichts an Iminify gesendet. „Verbinden“ öffnet iminify.com in einem neuen Tab, wo du diese Website freigibst.','A super admin can connect the whole network from the network admin instead, and every site joins it by itself.'=>'Ein Super-Administrator kann stattdessen das ganze Netzwerk über die Netzwerkverwaltung verbinden, und jede Website tritt automatisch bei.','How connecting works'=>'So funktioniert das Verbinden','Approve the connection on iminify.com, in the tab that opened. This page connects by itself once you do, and the site carries on connecting if you close it.'=>'Gib die Verbindung auf iminify.com im geöffneten Tab frei. Diese Seite verbindet sich danach automatisch, und die Website verbindet sich auch dann weiter, wenn du diese Seite schließt.','Open the page on iminify.com again'=>'Die Seite auf iminify.com erneut öffnen','An agency can add the site under <a>Settings, Sites</a> on iminify.com and paste its key here, or set it in wp-config.php as <code>IMINIFY_API_KEY</code>.'=>'Eine Agentur kann die Website unter „<a>Settings › Sites</a>“ auf iminify.com hinzufügen und ihren Schlüssel hier einfügen oder ihn in wp-config.php als <code>IMINIFY_API_KEY</code> festlegen.','An agency can add the site under Settings, Sites on iminify.com and paste its key here, or set it in wp-config.php as <code>IMINIFY_API_KEY</code>.'=>'Eine Agentur kann die Website unter „Settings › Sites“ auf iminify.com hinzufügen und ihren Schlüssel hier einfügen oder ihn in wp-config.php als <code>IMINIFY_API_KEY</code> festlegen.','An agency adds the network under <a>Settings, Sites</a> on iminify.com, with This is a multisite network ticked, and pastes its key here, or sets it in wp-config.php as <code>IMINIFY_API_KEY</code>.'=>'Eine Agentur fügt das Netzwerk unter „<a>Settings › Sites</a>“ auf iminify.com mit aktiviertem „This is a multisite network“ hinzu und fügt seinen Schlüssel hier ein oder legt ihn in wp-config.php als <code>IMINIFY_API_KEY</code> fest.','An agency adds the network under Settings, Sites on iminify.com, with This is a multisite network ticked, and pastes its key here, or sets it in wp-config.php as <code>IMINIFY_API_KEY</code>.'=>'Eine Agentur fügt das Netzwerk unter „Settings › Sites“ auf iminify.com mit aktiviertem „This is a multisite network“ hinzu und fügt seinen Schlüssel hier ein oder legt ihn in wp-config.php als <code>IMINIFY_API_KEY</code> fest.','Each upload is optimized in the background'=>'Jeder Upload wird im Hintergrund optimiert','WordPress finishes the upload first, then Iminify compresses the image and every size WordPress made of it.'=>'WordPress schließt zuerst den Upload ab, dann komprimiert Iminify das Bild und jede Größe, die WordPress davon erstellt hat.','An upload counts as one image'=>'Ein Upload zählt als ein Bild','The sizes WordPress made of it and its WebP and AVIF copies come with it as files, never as more images.'=>'Die Größen, die WordPress davon erstellt hat, und seine WebP- und AVIF-Kopien zählen als Dateien dazu, nie als weitere Bilder.','Your originals stay on this site'=>'Deine Originale bleiben auf dieser Website','A backup of each one is kept in the uploads folder, so any image can be put back as it was.'=>'Von jedem wird ein Backup im Uploads-Ordner behalten, sodass jedes Bild wieder in seinen ursprünglichen Zustand zurückgesetzt werden kann.','Your library goes when you say so'=>'Deine Mediathek folgt, wenn du es willst','Images already in the media library wait until you start them under Media, Bulk Optimization.'=>'Bilder, die bereits in der Mediathek sind, warten, bis du sie unter Medien › Massenoptimierung startest.','Once you connect'=>'Nach dem Verbinden','Connect with the network\'s key'=>'Mit dem Schlüssel des Netzwerks verbinden','Connect with a site key'=>'Mit einem Website-Schlüssel verbinden','Network key'=>'Netzwerkschlüssel','Site key'=>'Website-Schlüssel','Connect with this key'=>'Mit diesem Schlüssel verbinden','becomes'=>'wird zu','no change'=>'unverändert','%s’s settings'=>'Einstellungen von %s','Iminify found %s’s settings on this site. It can set this site’s settings to match them, as far as Iminify has the same settings: the compression level, the maximum width, metadata, WebP and AVIF copies, the sizes and backups. You see what changes before anything does.'=>'Iminify hat die Einstellungen von %s auf dieser Website gefunden. Es kann die Einstellungen dieser Website daran anpassen, soweit Iminify dieselben Einstellungen hat: die Komprimierungsstufe, die maximale Breite, Metadaten, WebP- und AVIF-Kopien, die Größen und Backups. Du siehst, was sich ändert, bevor sich etwas ändert.','Use %s’s settings'=>'Einstellungen von %s übernehmen','No thanks'=>'Nein danke','This site already uses what %s’s settings match.'=>'Diese Website verwendet bereits das, was den Einstellungen von %s entspricht.','From %s’s settings, Iminify would set these. Nothing changes until you use them, and using them replaces the changes you haven’t saved in the settings below.'=>'Aus den Einstellungen von %s würde Iminify Folgendes festlegen. Nichts ändert sich, bis du sie übernimmst, und das Übernehmen ersetzt die Änderungen, die du in den Einstellungen unten noch nicht gespeichert hast.','From %s’s settings, Iminify would set these. Nothing changes until you use them.'=>'Aus den Einstellungen von %s würde Iminify Folgendes festlegen. Nichts ändert sich, bis du sie übernimmst.','None of %s’s settings has a match in Iminify, so this site keeps its own.'=>'Keine der Einstellungen von %s hat eine Entsprechung in Iminify, daher behält diese Website ihre eigenen.','Use these settings'=>'Diese Einstellungen übernehmen','OK'=>'OK','In WordPress’s rewrite rules:'=>'In den Umschreibungsregeln von WordPress:','In <file />:'=>'In <file />:','<file /> holds the line %s, but the block it starts has no end of its own, or runs across another block, so the plugin leaves the file alone. Remove the block’s lines by hand.'=>'<file /> enthält die Zeile %s, aber der Block, den sie beginnt, hat kein eigenes Ende oder überschneidet sich mit einem anderen Block, daher lässt das Plugin die Datei unverändert. Entferne die Zeilen des Blocks von Hand.','The plugin can’t write to <file />. Remove these lines from it by hand, then reload Nginx.'=>'Das Plugin kann nicht in <file /> schreiben. Entferne diese Zeilen von Hand daraus und lade dann Nginx neu.','The plugin can’t write to <file />. Remove these lines from it by hand.'=>'Das Plugin kann nicht in <file /> schreiben. Entferne diese Zeilen von Hand daraus.','Every site of the network shares these lines, so someone who can manage the network removes them, from the network admin’s Iminify settings.'=>'Jede Website des Netzwerks teilt diese Zeilen, daher entfernt sie jemand, der das Netzwerk verwalten darf, in den Iminify-Einstellungen der Netzwerkverwaltung.','Every site of the network shares these lines, so a super admin removes them, on this page.'=>'Jede Website des Netzwerks teilt diese Zeilen, daher entfernt sie ein Super-Administrator auf dieser Seite.','Take %s’s rule out of WordPress’s rewrite rules? Every other rule stays.'=>'Die Regel von %s aus den Umschreibungsregeln von WordPress entfernen? Alle anderen Regeln bleiben.','Remove %s’s lines from this file? Everything else in it stays as it is. Nginx keeps them until it is reloaded, so reload it afterwards.'=>'Die Zeilen von %s aus dieser Datei entfernen? Alles andere darin bleibt unverändert. Nginx behält sie, bis es neu geladen wird, lade es daher danach neu.','Remove %s’s lines from this file? Everything else in it stays as it is.'=>'Die Zeilen von %s aus dieser Datei entfernen? Alles andere darin bleibt unverändert.','%s’s rewrite rule'=>'Umschreibungsregel von %s','%s’s rules'=>'Regeln von %s','Rules another optimizer left'=>'Regeln, die ein anderer Optimierer hinterlassen hat','The rules another optimizer left are gone.'=>'Die Regeln, die ein anderer Optimierer hinterlassen hat, sind entfernt.','An image optimizer you had before left these rules behind when it was switched off. Iminify never removes another plugin’s rules by itself.'=>'Ein Bildoptimierer, den du vorher hattest, hat diese Regeln hinterlassen, als er ausgeschaltet wurde. Iminify entfernt die Regeln eines anderen Plugins nie von selbst.','Open the network\'s Iminify settings'=>'Iminify-Einstellungen des Netzwerks öffnen','The network\'s connection'=>'Die Verbindung des Netzwerks','This is the network\'s main site, so it uses the network\'s connection to Iminify. A super admin connects and disconnects the network in the network admin.'=>'Das ist die Hauptwebsite des Netzwerks, daher nutzt sie die Verbindung des Netzwerks zu Iminify. Ein Super-Administrator verbindet und trennt das Netzwerk in der Netzwerkverwaltung.','This is the network\'s main site, so it uses the network\'s connection to Iminify, which isn\'t made yet. A super admin connects the network in the network admin, and every site joins it by itself.'=>'Das ist die Hauptwebsite des Netzwerks, daher nutzt sie die Verbindung des Netzwerks zu Iminify, die noch nicht hergestellt ist. Ein Super-Administrator verbindet das Netzwerk in der Netzwerkverwaltung, und jede Website tritt automatisch bei.','The network\'s sites'=>'Die Websites des Netzwerks','This key was made for a single site, so the network\'s sites can\'t join with it. Disconnect, then connect the network again, or make a key under Settings, Sites on iminify.com with This is a multisite network ticked.'=>'Dieser Schlüssel wurde für eine einzelne Website erstellt, daher können die Websites des Netzwerks damit nicht beitreten. Trenne die Verbindung und verbinde das Netzwerk erneut, oder erstelle unter „Settings › Sites“ auf iminify.com einen Schlüssel mit aktiviertem „This is a multisite network“.','Each site of the network joins by itself the first time it needs Iminify, with a key of its own, and starts with the main site\'s settings. Each counts as a site of its own on your account. A site disconnected on its own page, or under Settings, Sites on iminify.com, doesn\'t join again by itself.'=>'Jede Website des Netzwerks tritt automatisch mit einem eigenen Schlüssel bei, sobald sie Iminify zum ersten Mal braucht, und startet mit den Einstellungen der Hauptwebsite. Jede zählt in deinem Konto als eigene Website. Eine Website, deren Verbindung auf ihrer eigenen Seite oder unter „Settings › Sites“ auf iminify.com getrennt wurde, tritt nicht automatisch wieder bei.','Each site\'s settings are on its own Settings, Iminify page. The images in themes and other folders are the main site\'s to optimize, once for the whole network.'=>'Die Einstellungen jeder Website befinden sich auf ihrer eigenen Seite Einstellungen › Iminify. Die Bilder in Themes und weiteren Ordnern optimiert die Hauptwebsite, einmal für das ganze Netzwerk.','The main site\'s settings'=>'Einstellungen der Hauptwebsite','The main site\'s other folders'=>'Weitere Ordner der Hauptwebsite','How a network connects'=>'So wird ein Netzwerk verbunden','Join the network'=>'Dem Netzwerk beitreten','%s is connected to Iminify. This site can join it with a key of its own, and counts as a site of its own on the account.'=>'%s ist mit Iminify verbunden. Diese Website kann mit einem eigenen Schlüssel beitreten und zählt im Konto als eigene Website.','%d image is being optimized.'=>'%d Bild wird optimiert.' . "\0" . '%d Bilder werden optimiert.','%d image is waiting for the next batch.'=>'%d Bild wartet auf das nächste Kontingent.' . "\0" . '%d Bilder warten auf das nächste Kontingent.','%d image is waiting for the site to be connected. It goes out by itself once it is.'=>'%d Bild wartet darauf, dass die Website verbunden wird. Es wird automatisch gesendet, sobald sie verbunden ist.' . "\0" . '%d Bilder warten darauf, dass die Website verbunden wird. Sie werden automatisch gesendet, sobald sie verbunden ist.','The next batch opens on %s. New uploads go first, by themselves.'=>'Das nächste Kontingent wird am %s freigegeben. Neue Uploads kommen automatisch zuerst dran.','Queue'=>'Warteschlange','The server is low on disk space, so Iminify has stopped optimizing images here. Free some up, then optimize the images marked "Not optimized".'=>'Auf dem Server wird der Speicherplatz knapp, daher hat Iminify das Optimieren von Bildern hier eingestellt. Gib etwas frei und optimiere dann die Bilder mit der Markierung „Nicht optimiert“.','Your server answered with an error once the rules were in, so the plugin took them out again and your images load as before. Ask your host whether .htaccess files may set rewrite rules and file types, or choose picture tags.'=>'Dein Server hat mit einem Fehler geantwortet, nachdem die Regeln eingetragen waren, daher hat das Plugin sie wieder entfernt, und deine Bilder laden wie zuvor. Frag deinen Hoster, ob .htaccess-Dateien Umschreibungsregeln und Dateitypen festlegen dürfen, oder wähle picture-Tags.','Your server sends the WebP and AVIF copies. Checked %s.'=>'Dein Server liefert die WebP- und AVIF-Kopien aus. Geprüft am %s.','Your server still sends the originals: something answers for images before these rules are read, often Nginx in front of Apache. Add the Nginx lines below to its configuration, or choose picture tags. Checked %s.'=>'Dein Server liefert noch die Originale aus: Etwas beantwortet Bildanfragen, bevor diese Regeln gelesen werden, oft Nginx vor Apache. Füge die Nginx-Zeilen unten in dessen Konfiguration ein oder wähle picture-Tags. Geprüft am %s.','Your server still sends the originals. Add the lines below to its configuration and reload Nginx, then save again. Checked %s.'=>'Dein Server liefert noch die Originale aus. Füge die Zeilen unten in seine Konfiguration ein und lade Nginx neu, dann speichere erneut. Geprüft am %s.','Cloudflare answered with the original, so a visitor may never get a copy through these rules. Choose picture tags, which work behind Cloudflare. Checked %s.'=>'Cloudflare hat mit dem Original geantwortet, daher bekommt ein Besucher über diese Regeln möglicherweise nie eine Kopie. Wähle picture-Tags, die hinter Cloudflare funktionieren. Geprüft am %s.','The plugin couldn\'t ask your site for an image to see whether the rules work, which happens when a site can\'t reach its own address. Open one of your images with a browser\'s developer tools: its type should read image/avif or image/webp. Tried %s.'=>'Das Plugin konnte deine Website nicht nach einem Bild fragen, um zu prüfen, ob die Regeln funktionieren. Das passiert, wenn eine Website ihre eigene Adresse nicht erreichen kann. Öffne eines deiner Bilder mit den Entwicklerwerkzeugen eines Browsers: Sein Typ sollte image/avif oder image/webp lauten. Versucht am %s.','The rules are in <file />.'=>'Die Regeln stehen in <file />.','<file /> holds the line <begin /> without its <end /> line, so the plugin leaves the file alone. Put the line <end /> back after the block’s last <closing />, or delete every line of the block, then save again.'=>'<file /> enthält die Zeile <begin /> ohne ihre Zeile <end />, daher lässt das Plugin die Datei unverändert. Setze die Zeile <end /> nach dem letzten <closing /> des Blocks wieder ein oder lösche alle Zeilen des Blocks und speichere dann erneut.','Your uploads folder isn\'t inside the folder that holds the site\'s .htaccess file, so no rule there can name it. Choose picture tags.'=>'Dein Uploads-Ordner liegt nicht innerhalb des Ordners, der die .htaccess-Datei der Website enthält, daher kann ihn keine Regel dort erfassen. Wähle picture-Tags.','There’s no <file /> yet. Create it with these lines, then save again.'=>'<file /> existiert noch nicht. Erstelle die Datei mit diesen Zeilen und speichere dann erneut.','<file /> doesn’t turn on rewriting, so the plugin leaves it alone. If your server reads rewrite rules there, paste these lines into it, then save again.'=>'<file /> aktiviert das Umschreiben nicht, daher lässt das Plugin die Datei unverändert. Wenn dein Server dort Umschreibungsregeln liest, füge diese Zeilen in die Datei ein und speichere dann erneut.','The plugin can’t write to <file />. Paste these lines into it, above the rules WordPress gave the network, then save again.'=>'Das Plugin kann nicht in <file /> schreiben. Füge diese Zeilen dort oberhalb der Regeln ein, die WordPress für das Netzwerk eingetragen hat, und speichere dann erneut.','The plugin can’t write to <file />. Paste these lines at its end, then save again.'=>'Das Plugin kann nicht in <file /> schreiben. Füge diese Zeilen am Ende der Datei ein und speichere dann erneut.','Your server reads neither .htaccess files nor Nginx\'s configuration, so the plugin has no rules to give it. Choose picture tags.'=>'Dein Server liest weder .htaccess-Dateien noch die Konfiguration von Nginx, daher hat das Plugin keine Regeln für ihn. Wähle picture-Tags.','Your site runs on Nginx, which doesn\'t read .htaccess. Put the first lines at the top of the site\'s server block, before any if or rewrite, and the location above any other location for images, then reload Nginx. Copy into the location any expires, Cache-Control or add_header lines your images need, since its add_header replaces the server block\'s:'=>'Deine Website läuft auf Nginx, das .htaccess nicht liest. Setze die ersten Zeilen an den Anfang des server-Blocks der Website, vor jedes if oder rewrite, und die location über jede andere location für Bilder, und lade Nginx dann neu. Kopiere alle expires-, Cache-Control- oder add_header-Zeilen, die deine Bilder brauchen, in die location, da ihr add_header das des server-Blocks ersetzt:','For Nginx, put the first lines at the top of the site\'s server block, before any if or rewrite, and the location above any other location for images, then reload Nginx. Copy into the location any expires, Cache-Control or add_header lines your images need, since its add_header replaces the server block\'s:'=>'Setze für Nginx die ersten Zeilen an den Anfang des server-Blocks der Website, vor jedes if oder rewrite, und die location über jede andere location für Bilder, und lade Nginx dann neu. Kopiere alle expires-, Cache-Control- oder add_header-Zeilen, die deine Bilder brauchen, in die location, da ihr add_header das des server-Blocks ersetzt:','They cover: %s.'=>'Sie umfassen: %s.','They serve any WebP or AVIF copy named after an image beside it, so a copy another optimizer left there is served too until Iminify makes its own. Iminify never deletes another plugin’s copies.'=>'Sie liefern jede WebP- oder AVIF-Kopie aus, die nach einem Bild daneben benannt ist, sodass auch eine Kopie, die ein anderer Optimierer dort hinterlassen hat, ausgeliefert wird, bis Iminify eine eigene erstellt. Iminify löscht nie die Kopien eines anderen Plugins.','Cloudflare answers for your site. It keeps one version of each image whatever the browser reads, so a browser that can\'t show AVIF could get the AVIF copy. Choose picture tags, which work behind any CDN.'=>'Cloudflare beantwortet die Anfragen an deine Website. Es speichert eine Version jedes Bildes, unabhängig davon, was der Browser lesen kann, daher könnte ein Browser, der kein AVIF anzeigen kann, die AVIF-Kopie erhalten. Wähle picture-Tags, die hinter jedem CDN funktionieren.','WP Offload Media serves your images from its bucket, which these rules never reach, so those keep their originals. With its “Remove Local Media” on, the rules serve nothing.'=>'WP Offload Media liefert deine Bilder aus seinem Bucket aus, den diese Regeln nie erreichen, daher behalten diese Bilder ihre Originale. Mit aktiviertem „Remove Local Media“ liefern die Regeln nichts aus.','Also reaches the images in raw HTML, page builders and your theme\'s own markup, the backgrounds set in the page itself, and the images in the folders you chose, by reading each page as it\'s sent. A background set in a stylesheet file keeps its original. A page your cache hasn\'t kept takes a little longer.'=>'Erfasst auch die Bilder in reinem HTML, in Page Buildern und im eigenen Markup deines Themes, die direkt in der Seite gesetzten Hintergründe und die Bilder in den von dir gewählten Ordnern, indem jede Seite beim Ausliefern gelesen wird. Ein Hintergrund aus einer Stylesheet-Datei behält sein Original. Eine Seite, die dein Cache nicht gespeichert hat, braucht etwas länger.','Your pages stay as they are, and your server sends the WebP or AVIF copy in place of the image to each browser that reads it. That reaches every image in the uploads folder and the folders you chose, backgrounds in stylesheet files too. Needs rules in your server’s configuration, written for you on Apache, and behind a CDN, one that keeps a version of each image per format.'=>'Deine Seiten bleiben unverändert, und dein Server liefert jedem Browser, der die WebP- oder AVIF-Kopie lesen kann, diese anstelle des Bildes aus. Das erfasst jedes Bild im Uploads-Ordner und in den von dir gewählten Ordnern, auch Hintergründe in Stylesheet-Dateien. Erfordert Regeln in der Konfiguration deines Servers, die auf Apache für dich geschrieben werden, und hinter einem CDN eines, das pro Format eine Version jedes Bildes speichert.','Your pages stay as they are: the copies are made, but no page names them.'=>'Deine Seiten bleiben unverändert: Die Kopien werden erstellt, aber keine Seite verweist auf sie.','For the images in your posts and those your theme shows through WordPress. Each page is the same for every visitor, so page caches and CDNs keep working, and a browser that reads neither format gets the original.'=>'Für die Bilder in deinen Beiträgen und die, die dein Theme über WordPress anzeigt. Jede Seite ist für jeden Besucher gleich, sodass Seiten-Caches und CDNs weiter funktionieren, und ein Browser, der keines der beiden Formate lesen kann, erhält das Original.','Optimization'=>'Optimierung','These settings are kept with the site on iminify.com, which applies them to every image the site sends.'=>'Diese Einstellungen werden mit der Website auf iminify.com gespeichert, das sie auf jedes Bild anwendet, das die Website sendet.','Send each image to Iminify as it is uploaded.'=>'Jedes Bild beim Hochladen an Iminify senden.','A WebP copy of every size, served to browsers that read it. A copy larger than its image isn\'t kept.'=>'Eine WebP-Kopie jeder Größe, ausgeliefert an Browser, die sie lesen können. Eine Kopie, die größer als ihr Bild ist, wird nicht behalten.','An AVIF copy of every size too: usually smaller than WebP, and slower to make.'=>'Zusätzlich eine AVIF-Kopie jeder Größe: meist kleiner als WebP und langsamer zu erstellen.','Any width'=>'Beliebige Breite','Shrinks a wider main image to this width. Leave it empty to keep each image\'s width.'=>'Verkleinert ein breiteres Hauptbild auf diese Breite. Leer lassen, um die Breite jedes Bildes zu behalten.','Fits the main image under this size. Leave it empty for no limit.'=>'Bringt das Hauptbild unter diese Dateigröße. Leer lassen für kein Limit.','Keeps each image\'s EXIF data, such as the camera and the place it was taken. Off removes it.'=>'Behält die EXIF-Daten jedes Bildes, etwa die Kamera und den Aufnahmeort. Ausgeschaltet werden sie entfernt.','Describes each image that has no alt text. An alt text you wrote is never replaced. A small copy of the image goes to Anthropic\'s AI, and each one counts against your AI alt texts for the day.'=>'Beschreibt jedes Bild ohne Alternativtext. Ein Alternativtext, den du geschrieben hast, wird nie ersetzt. Eine verkleinerte Version des Bildes geht an die KI von Anthropic, und jedes Bild wird auf deine KI-Alternativtexte für heute angerechnet.','Language of the alt text'=>'Sprache des Alternativtexts','Optimize every size'=>'Alle Größen optimieren','Every size WordPress makes of an upload. Turn it off to pick the sizes.'=>'Alle Größen, die WordPress von einem Upload erstellt. Schalte die Option aus, um die Größen auszuwählen.','On this site'=>'Auf dieser Website','Kept in the uploads folder under iminify-backup, so any image can be restored as it was.'=>'Im Uploads-Ordner unter iminify-backup gespeichert, sodass jedes Bild in seinem ursprünglichen Zustand wiederhergestellt werden kann.','WebP and AVIF on your pages'=>'WebP und AVIF auf deinen Seiten','Serve them with picture tags'=>'Über picture-Tags ausliefern','Serve them on the whole page'=>'Auf der ganzen Seite ausliefern','Serve them through server rules'=>'Über Serverregeln ausliefern','Don\'t change the pages'=>'Seiten nicht ändern','Add the width, height and alt text images lack'=>'Fehlende Breite, Höhe und Alternativtexte von Bildern ergänzen','Where a page’s markup leaves them out of an image from your media library, the plugin adds its width and height, so the page doesn’t jump as it loads, and the alt text it has in the library, as each page is sent. An alt text left empty on purpose stays empty.'=>'Wo das Markup einer Seite sie bei einem Bild aus deiner Mediathek weglässt, ergänzt das Plugin beim Ausliefern jeder Seite dessen Breite und Höhe, damit die Seite beim Laden nicht springt, und den Alternativtext, den es in der Mediathek hat. Ein absichtlich leer gelassener Alternativtext bleibt leer.','When you delete the plugin'=>'Wenn du das Plugin löschst','Also delete the WebP and AVIF copies'=>'Auch die WebP- und AVIF-Kopien löschen','A page your cache kept with picture tags would show a broken image until the cache is cleared.'=>'Eine Seite, die dein Cache mit picture-Tags gespeichert hat, würde ein defektes Bild zeigen, bis der Cache geleert ist.','Also delete the backups'=>'Auch die Backups löschen','They\'re the only originals of the images Iminify optimized, so those images can\'t be restored afterwards. With the copies deleted too, installing the plugin again would optimize those images a second time.'=>'Sie sind die einzigen Originale der Bilder, die Iminify optimiert hat, daher können diese Bilder danach nicht wiederhergestellt werden. Wenn auch die Kopien gelöscht sind, würde eine erneute Installation des Plugins diese Bilder ein zweites Mal optimieren.','Save changes'=>'Änderungen speichern','Unsaved changes'=>'Ungespeicherte Änderungen']];